type RuleActionPinning struct {
	RuleBase
	// overriddenLevel is set from the CLI flag to override the pinning level from config.
	overriddenLevel *PinLevel
	// overriddenEnabled is true when the CLI flag enables the rule even if config disables it.
	overriddenEnabled bool
}

// NewRuleActionPinning creates a new RuleActionPinning instance.
func NewRuleActionPinning() *RuleActionPinning {
	return &RuleActionPinning{
		RuleBase: RuleBase{
			name: "action-pinning",
			desc: "Checks that action and reusable workflow references use pinned versions",
		},
	}
}

// SetOverriddenLevel sets the CLI-overridden pinning level and enables the rule.
func (rule *RuleActionPinning) SetOverriddenLevel(level PinLevel) {
	rule.overriddenLevel = &level
	rule.overriddenEnabled = true
}

// getConfig returns the merged action-pinning configuration for the given file path.
func (rule *RuleActionPinning) getConfig(path string) *mergedActionPinningConfig {
	cfg := rule.Config()
	if cfg == nil && !rule.overriddenEnabled {
		return nil
	}

	m := &mergedActionPinningConfig{
		enabled: false,
	}

