$withCache(config?: { config?: CacheConfig; tag?: string; autoInvalidate?: boolean } | false) {
	this.cacheConfig = config === undefined
		? { config: {}, enable: true, autoInvalidate: true }
		: config === false
		? { enable: false }
		: { enable: true, autoInvalidate: true, ...config };
