/**
 * Build a `RANGE BETWEEN ... AND ...` frame clause.
 *
 * @param spec - an object with `from` and `to` boundary values.
 */
export function range(spec: FrameSpec): SQL {
	if (isBefore(spec.from, spec.to)) {
		throw new Error(
			`frame start (from) must not be ordered after frame end (to)`,
		);
	}
	return sql`range between ${spec.from} and ${spec.to}`;
}

// ──────────────────────────────────────────────
// WindowSpec type used in inline OVER definitions
// ──────────────────────────────────────────────

export interface WindowSpec {
	partitionBy?: (AnyColumn | SQLWrapper)[];
	orderBy?: (AnyColumn | SQL | SQL.Aliased)[];
	frame?: SQL;
}

/** @internal */
export function buildWindowSpec(spec: WindowSpec): SQL {
	const parts: SQL[] = [];

	if (spec.partitionBy && spec.partitionBy.length > 0) {
		parts.push(sql`partition by ${sql.join(spec.partitionBy, sql`, `)}`);
	}

	if (spec.orderBy && spec.orderBy.length > 0) {
		parts.push(sql`order by ${sql.join(spec.orderBy, sql`, `)}`);
	}

	if (spec.frame) {
		parts.push(spec.frame);
	}

	return sql.join(parts, sql` `);
}

