console.log('\n=== AC 2: Positional-argument functions accept optional trailing args ===\n');

assertEqual(sqlText(ntile(10).over()), 'ntile(10) over ()', 'ntile(10)');
assertEqual(sqlText(nthValue(sql`val`, 5).over()), 'nth_value(val, 5) over ()', 'nthValue(sql`val`, 5)');
