// ─────────────────────────────────────────────────────────────────────────
console.log('\n=== AC 6: .window(name, spec) validation (empty / whitespace) ===\n');

// Simulate the builder's validation logic
function testWindowName(name) {
	if (name.trim().length === 0) {
		if (name.length === 0) throw new Error('Window name must be a non-empty string');
		throw new Error('Window name must not contain only whitespace');
