// ─────────────────────────────────────────────────────────────────────────
console.log('\n=== AC 7: All helpers, constants, and frame utilities are exported ===\n');

const exports = {
	rowNumber, rank, denseRank, ntile, percentRank, cumeDist,
	lag, lead, firstValue, lastValue, nthValue,
	windowSum, windowAvg, windowMin, windowMax, windowCount,
	unboundedPreceding, currentRow, unboundedFollowing,
	preceding, following, rows, range,
	WindowBuilder,
};
for (const [name, value] of Object.entries(exports)) {
	assert(value !== undefined, `${name} is exported`);
}

// ─────────────────────────────────────────────────────────────────────────
console.log('\n=== AC 8: windowCount() without arg emits count(*) ===\n');

assertEqual(sqlText(windowCount().over()), 'count(*) over ()', 'windowCount().over() -> count(*)');
assertEqual(sqlText(windowCount(sql`salary`).over()), 'count(salary) over ()', 'windowCount(expr).over() -> count(expr)');

// ─────────────────────────────────────────────────────────────────────────
console.log('\n=== AC 9: Validation — ntile / nthValue reject non-positive ===\n');

assertThrows(() => ntile(0), 'ntile', 'ntile(0) throws with function name');
assertThrows(() => ntile(-1), 'ntile', 'ntile(-1) throws');
assertThrows(() => ntile(-5), '-5', 'ntile(-5) includes received value');
assertThrows(() => ntile(1.5), 'ntile', 'ntile(1.5) throws (non-integer)');
assertThrows(() => nthValue(sql`x`, 0), 'nthValue', 'nthValue(x,0) throws');
assertThrows(() => nthValue(sql`x`, -3), 'nthValue', 'nthValue(x,-3) throws');
assertThrows(() => nthValue(sql`x`, -3), '-3', 'nthValue(x,-3) includes received value');

