assertThrows(() => preceding(-1), 'preceding', 'preceding(-1) throws');
assertThrows(() => preceding(1.5), 'preceding', 'preceding(1.5) throws (non-integer)');
assertThrows(() => following(-5), 'following', 'following(-5) throws');
assertThrows(() => following(3.14), 'following', 'following(3.14) throws (non-integer)');

// ─────────────────────────────────────────────────────────────────────────
console.log('\n=== AC 11: rows / range reject from>to with "from" in error ===\n');

assertThrows(
	() => rows({ from: following(5), to: currentRow }),
	'from',
	'rows({from:following(5), to:currentRow}) — "from" in error',
);
assertThrows(
	() => rows({ from: following(3), to: preceding(2) }),
	'from',
	'rows({from:following(3), to:preceding(2)}) — "from" in error',
);
assertThrows(
	() => range({ from: following(3), to: unboundedPreceding }),
	'from',
