console.log('\n=== AC 12: Numeric positional args never become bound parameters ===\n');

assertZeroParams(ntile(10).over(), 'ntile(10) — 0 params');
assertZeroParams(nthValue(sql`salary`, 7).over(), 'nthValue(expr, 7) — 0 params');
assertZeroParams(lag(sql`salary`, 3).over(), 'lag(expr, 3) — 0 params');
assertZeroParams(lead(sql`salary`, 2).over(), 'lead(expr, 2) — 0 params');

// preceding/following in frame
const frameQuery = windowSum(sql`salary`).over({
	frame: rows({ from: preceding(5), to: following(10) }),
});
assertZeroParams(frameQuery, 'preceding(5)/following(10) in frame — 0 params');
const fq = queryWithParams(frameQuery);
assert(fq.sql.includes('5 preceding'), 'frame SQL contains "5 preceding"');
assert(fq.sql.includes('10 following'), 'frame SQL contains "10 following"');

