package http

import (
	"fmt"
	"math"
	h "net/http"
	"strconv"
	"strings"
	"time"

	"github.com/caarlos0/log"
	"github.com/goreleaser/goreleaser/v2/pkg/config"
	"github.com/goreleaser/goreleaser/v2/pkg/context"
)

// retryableStatuses are the HTTP status codes that trigger a retry for uploads and artifactories.
var retryableStatuses = map[int]bool{
	408: true, // Request Timeout
	429: true, // Too Many Requests
	500: true, // Internal Server Error
	502: true, // Bad Gateway
	503: true, // Service Unavailable
	504: true, // Gateway Timeout
}

const defaultRetryAttempts = 1 // no retry by default
const defaultRetryDelay = 1 * time.Second

// isRetryableHTTPStatus returns true if the HTTP status code is retryable.
func isRetryableHTTPStatus(status int) bool {
	return retryableStatuses[status]
}

// isRetryableHTTPError returns true if the error is a transport-level error
// (non-2xx/3xx HTTP responses are handled separately via status code checks).
func isRetryableHTTPError(err error) bool {
	// Transport errors like connection refused, DNS failure, TLS handshake failure, etc.
	// are already retryable. We don't need to further filter since the caller
	// checks HTTP status separately.
	return err != nil
}

// retryAfterDelay parses the Retry-After header and returns the duration to wait.
// It supports both delta-seconds (integer) and HTTP-date formats.
// Returns 0 if the header is missing or invalid.
func retryAfterDelay(resp *h.Response) time.Duration {
	header := resp.Header.Get("Retry-After")
	if header == "" {
		return 0
	}

	// Try delta-seconds first
	if seconds, err := strconv.Atoi(header); err == nil && seconds > 0 {
		return time.Duration(seconds) * time.Second
	}

	// Try HTTP-date format
	if t, err := h.ParseTime(header); err == nil {
		delay := time.Until(t)
		if delay > 0 {
			return delay
		}
		return 0
	}

	return 0
}

// backoffDelay computes the exponential backoff delay for the given attempt.
// attempt is 0-based. base is the initial delay.
func backoffDelay(attempt int, base time.Duration) time.Duration {
	if attempt <= 0 {
		return base
	}
	// Exponential backoff: base * 2^attempt, with jitter-free for determinism
	delay := time.Duration(float64(base) * math.Pow(2, float64(attempt)))
	return delay
}

// retryWait computes the actual wait time for a retry attempt.
// It uses exponential backoff, and for 429/503 responses, also considers Retry-After.
// The returned duration is capped by maxDelay.
func retryWait(attempt int, base, maxDelay time.Duration, resp *h.Response) time.Duration {
	delay := backoffDelay(attempt, base)

	// For 429 and 503, consider Retry-After header
	if resp != nil {
		status := resp.StatusCode
		if status == 429 || status == 503 {
			if ra := retryAfterDelay(resp); ra > 0 {
				if ra > delay {
					delay = ra
				}
			}
		}
	}

	// Cap by max delay
	if maxDelay > 0 && delay > maxDelay {
		delay = maxDelay
	}

	return delay
}

// recordAttempt records a publish attempt in the context.
func recordAttempt(ctx *context.Context, publisher, instance, target string, attempt int, status string, errStr string) {
	ctx.PublishAttempts = append(ctx.PublishAttempts, context.PublishAttempt{
		Publisher: publisher,
		Instance:  instance,
		Target:    target,
		Attempt:   attempt,
		Status:    status,
		Error:     errStr,
	})
}

// doWithRetry executes the given function with retry logic for HTTP uploads/artifactories.
// It retries on transport errors and specific HTTP status codes (408, 429, 500, 502, 503, 504).
// For 429 and 503, it considers the Retry-After header.
// It records each attempt in ctx.PublishAttempts.
func doWithRetry(ctx *context.Context, upload *config.Upload, publisher, instance, target string, fn func() error) error {
	retry := upload.Retry
	attempts := retry.Attempts
	delay := retry.Delay
	maxDelay := retry.MaxDelay

	// Default: no retry
	if attempts <= 0 {
		attempts = defaultRetryAttempts
	}
	if delay <= 0 {
		delay = defaultRetryDelay
	}

	var lastErr error
	for attempt := 1; attempt <= attempts; attempt++ {
		// Check context cancellation before each attempt
		select {
		case <-ctx.Done():
			lastErr = ctx.Err()
			recordAttempt(ctx, publisher, instance, target, attempt, "failure", lastErr.Error())
			return lastErr
		default:
		}

		err := fn()
		if err == nil {
			recordAttempt(ctx, publisher, instance, target, attempt, "success", "")
			return nil
		}

		// Record the failure
		recordAttempt(ctx, publisher, instance, target, attempt, "failure", err.Error())
		lastErr = err

		// Check if we should retry
		if attempt >= attempts {
			break
		}

		var resp *h.Response
		if httpErr, ok := err.(httpError); ok {
			resp = httpErr.Response
			if !isRetryableHTTPStatus(resp.StatusCode) {
				return err
			}
		} else {
			// Transport error - retryable
		}

		// On the last permitted attempt, don't sleep, just return the error
		wait := retryWait(attempt-1, delay, maxDelay, resp)
		log.WithField("attempt", attempt).
			WithField("max_attempts", attempts).
			WithField("wait", wait).
			WithError(err).
			Debug("retrying after error")
		time.Sleep(wait)
	}

	return lastErr
}

// httpError wraps an HTTP response error with the response itself.
type httpError struct {
	Response *h.Response
	Err      error
}

func (e httpError) Error() string {
	return e.Err.Error()
}

func (e httpError) Unwrap() error {
	return e.Err
}

