// isTransientBlobError checks if the error is a transient error that should be retried.
// It returns true if the error implements Timeout() bool or Temporary() bool and returns true.
func isTransientBlobError(err error) bool {
	type timeoutable interface {
		Timeout() bool
	}
	type temporaryable interface {
		Temporary() bool
	}

	if t, ok := err.(timeoutable); ok && t.Timeout() {
		return true
	}
	if t, ok := err.(temporaryable); ok && t.Temporary() {
		return true
	}
	return false
}

