// transientError implements the Timeout() interface for testing transient errors.
type transientError struct {
	msg string
}

func (e *transientError) Error() string { return e.msg }
func (e *transientError) Timeout() bool { return true }

// nonTransientError does not implement Timeout() or Temporary().
type nonTransientError struct {
	msg string
}

func (e *nonTransientError) Error() string { return e.msg }

// mockUploader implements uploader for testing.
type mockUploader struct {
	openAttempts  int
	uploadAttempts int
	openFailCount   int    // number of times Open should fail before succeeding
	uploadFailCount int   // number of times Upload should fail before succeeding
	transient       bool  // whether failures are transient (Timeout()=true)
	mu              sync.Mutex
}

func (m *mockUploader) Close() error { return nil }

func (m *mockUploader) Open(_ *context.Context, _ string) error {
	m.mu.Lock()
	defer m.mu.Unlock()
	m.openAttempts++
	if m.openAttempts <= m.openFailCount {
		if m.transient {
			return &transientError{msg: "transient open error"}
		}
		return &nonTransientError{msg: "non-transient open error"}
	}
	return nil
}

func (m *mockUploader) Upload(_ *context.Context, _ string, _ []byte) error {
	m.mu.Lock()
	defer m.mu.Unlock()
	m.uploadAttempts++
	if m.uploadAttempts <= m.uploadFailCount {
		if m.transient {
			return &transientError{msg: "transient upload error"}
		}
		return &nonTransientError{msg: "non-transient upload error"}
	}
	return nil
}

