	ctx.Artifacts.Add(&artifact.Artifact{
		Name: "test.bin",
		Path: file,
		Type: artifact.UploadableBinary,
	})

	up := &mockUploader{
		openFailCount:   0,
		uploadFailCount: 1, // fail once, succeed on retry
