	}

	// First attempt should be failure
	require.Equal(t, "failure", attempts[0].Status)
	require.Contains(t, attempts[0].Error, "transient upload error")

	// Second attempt should be success
	require.Equal(t, "success", attempts[1].Status)
	require.Empty(t, attempts[1].Error)
}

