// TestBlobRetry_UploadPublishAttemptsOrdering verifies that
// publish_attempts entries are in the correct order (failures before success).
func TestBlobRetry_UploadPublishAttemptsOrdering(t *testing.T) {
	content := []byte("test data")
	folder := t.TempDir()
	file := filepath.Join(folder, "test.bin")
	require.NoError(t, os.WriteFile(file, content, 0o644))

	ctx := testctx.WrapWithCfg(t.Context(), config.Project{
		ProjectName: "testproj",
		Blobs: []config.Blob{
			{
				Provider: "s3",
				Bucket:   "test-bucket",
				Directory: "releases/{{.Version}}",
				Retry: &config.RetryConfig{
					Attempts: 5,
					Delay:    5 * time.Millisecond,
				},
			},
		},
	}, testctx.WithVersion("1.2.3"))

	ctx.Artifacts.Add(&artifact.Artifact{
		Name: "test.bin",
		Path: file,
		Type: artifact.UploadableBinary,
	})

	up := &mockUploader{
		openFailCount:   0,
		uploadFailCount: 3, // fail 3 times, succeed on 4th
		transient:       true,
	}

	err := openBucketWithRetry(ctx, up, "s3://test-bucket", ctx.Config.Blobs[0].Retry)
	require.NoError(t, err)

	err = uploadDataWithRetry(ctx, ctx.Config.Blobs[0], up, file, "releases/1.2.3/test.bin", "s3://test-bucket")
	require.NoError(t, err)

	arts := ctx.Artifacts.List()
	require.Len(t, arts, 1)
	attempts := artifact.MustExtra[[]http.PublishAttemptsEntry](*arts[0], http.ExtraPublishAttempts)
	require.Len(t, attempts, 4) // 3 failures + 1 success

	// First 3 should be failures, last should be success
	for i := 0; i < 3; i++ {
		require.Equal(t, "failure", attempts[i].Status, "attempt %d should be failure", i+1)
		require.Equal(t, i+1, attempts[i].Attempt)
	}
	require.Equal(t, "success", attempts[3].Status)
	require.Equal(t, 4, attempts[3].Attempt)
}

