// underlying connection in priority order.
func (s *MuxSession) writeLoop() {
	for {
		select {
		case <-s.die:
			return
		case <-s.writeSignal:
			// Drain all queued frames under the lock.
			var frames []muxFrame
			s.writeMu.Lock()
			if len(s.writeQueue) > 0 {
				frames = s.writeQueue
				s.writeQueue = make([]muxFrame, 0, 128)
			}
			s.writeMu.Unlock()

			if len(frames) == 0 {
				continue
			}

			// Sort frames into priority buckets.
			type bucket struct {
				frames []muxFrame
			}
			var buckets [3]bucket

			for _, f := range frames {
				prio := f.priority
				if prio > MuxPriorityLow {
					prio = MuxPriorityNormal
				}
				// Control frames always go to the high priority bucket.
				if f.frameType != muxTypeData {
					prio = MuxPriorityHigh
				}
				buckets[prio].frames = append(buckets[prio].frames, f)
			}

			// Flush high, then normal, then low.
			for prio := uint8(MuxPriorityHigh); prio <= MuxPriorityLow; prio++ {
				b := &buckets[prio]
				for _, f := range b.frames {
					if err := s.writeFrame(f); err != nil {
						// Write error — session will be torn down by readLoop or Close.
						return
					}
				}
				b.frames = b.frames[:0]
			}
		}
	}
