func (s *MuxSession) writeLoop() {
	type bucket struct {
		frames []muxFrame
	}
	// Index 0 = high, 1 = normal, 2 = low.
	var buckets [3]bucket

	flush := func() error {
		for prio := uint8(MuxPriorityHigh); prio <= MuxPriorityLow; prio++ {
			b := &buckets[prio]
			for _, f := range b.frames {
				if err := s.writeFrame(f); err != nil {
					return err
				}
			}
			b.frames = b.frames[:0]
		}
		return nil
	}

	for {
		select {
		case <-s.die:
			return
		case f := <-s.writeCh:
			prio := f.priority
			if prio > MuxPriorityLow {
				prio = MuxPriorityNormal
			}
			// Non-data (control) frames always go to the high priority bucket.
			if f.frameType != muxTypeData {
				prio = MuxPriorityHigh
			}
			buckets[prio].frames = append(buckets[prio].frames, f)

			// Batch additional queued frames.
		drain:
			for i := 0; i < 64; i++ {
				select {
				case f2 := <-s.writeCh:
					p := f2.priority
					if p > MuxPriorityLow {
						p = MuxPriorityNormal
					}
					if f2.frameType != muxTypeData {
						p = MuxPriorityHigh
					}
					buckets[p].frames = append(buckets[p].frames, f2)
				default:
					break drain
				}
			}

			if err := flush(); err != nil {
				// Write error — the session will be torn down by readLoop or Close.
				return
			}
		}
	}
}"}

