func (s *MuxStream) Read(b []byte) (int, error) {
	if s.isGone() {
		return 0, io.ErrClosedPipe
	}

	s.session.mu.Lock()
	defer s.session.mu.Unlock()

	for {
		// Check for a stream-level error (e.g. deadline).
		if err := s.loadError(); err != nil {
			return 0, err
		}

		if s.recvClosed && len(s.recvBuf) == 0 {
			return 0, io.EOF
		}

		if len(s.recvBuf) > 0 {
			n := copy(b, s.recvBuf)
			s.recvBuf = s.recvBuf[n:]

			// If we have drained the buffer and both sides are closed, mark drained.
			if len(s.recvBuf) == 0 && s.localClosed && s.remoteClosed {
				s.drained = true
				s.session.maybeDeleteStreamLocked(s.id)
			}

			// Send window update so remote can send more.
			s.session.sendWindowUpdateLocked(s.id, n)
			return n, nil
		}

		// Wait for data or a wake-up event.
		ch := s.readSignal
		s.session.mu.Unlock()
		<-ch
		s.session.mu.Lock()
	}
}

