{"file_path": "mux_test.go", "content": "package kcp

import (
	"io"
	"net"
	"sync"
	"sync/atomic"
	"testing"
	"time"
)

// pipePair creates a pair of connected MuxSessions over net.Pipe for testing.
// The client side uses odd stream IDs, server side uses even stream IDs.
func pipePair(t testing.TB, cfg *MuxConfig) (client, server *MuxSession) {
	t.Helper()
	c, s := net.Pipe()

	clientCfg := DefaultMuxConfig()
	clientCfg.Side = MuxSideClient
	serverCfg := DefaultMuxConfig()
	serverCfg.Side = MuxSideServer

	// Apply custom config overrides if provided
	if cfg != nil {
		if cfg.MaxFrameSize > 0 {
			clientCfg.MaxFrameSize = cfg.MaxFrameSize
			serverCfg.MaxFrameSize = cfg.MaxFrameSize
		}
		if cfg.SendWindow > 0 {
			clientCfg.SendWindow = cfg.SendWindow
			serverCfg.SendWindow = cfg.SendWindow
		}
		if cfg.RecvWindow > 0 {
			clientCfg.RecvWindow = cfg.RecvWindow
			serverCfg.RecvWindow = cfg.RecvWindow
		}
	}

	var err error
	client, err = NewMuxSession(c, &clientCfg)
	if err != nil {
		t.Fatal("NewMuxSession(client):", err)
	}
	server, err = NewMuxSession(s, &serverCfg)
	if err != nil {
		t.Fatal("NewMuxSession(server):", err)
	}
	return
}

func closePair(t testing.TB, client, server *MuxSession) {
	t.Helper()
	client.Close()
	server.Close()
}

func TestMuxSessionClose(t *testing.T) {
	client, server := pipePair(t, nil)
	defer closePair(t, client, server)

	if err := client.Close(); err != nil {
		t.Fatal("client.Close():", err)
	}
}

func TestMuxOpenAccept(t *testing.T) {
	client, server := pipePair(t, nil)
	defer closePair(t, client, server)

	// Client opens a stream
	var (
		cst *MuxStream
		sst *MuxStream
		wg  sync.WaitGroup
	)

	wg.Add(1)
	go func() {
		defer wg.Done()
		var err error
		cst, err = client.OpenStream(MuxPriorityNormal)
		if err != nil {
			t.Error("client.OpenStream:", err)
		}
	}()

	wg.Add(1)
	go func() {
		defer wg.Done()
		var err error
		sst, err = server.AcceptStream()
		if err != nil {
			t.Error("server.AcceptStream:", err)
		}
	}()

	wg.Wait()

	if cst == nil || sst == nil {
		t.Fatal("streams should not be nil")
	}

	// Check ID parity
	if cst.ID()%2 != 1 {
		t.Errorf("client stream ID %d should be odd", cst.ID())
	}
	if sst.ID()%2 != 0 {
		t.Errorf("server stream ID %d should be even", sst.ID())
	}
	// IDs should match (same stream, different sides)
	if cst.ID() != sst.ID() {
		t.Errorf("stream IDs should match: client=%d server=%d", cst.ID(), sst.ID())
	}
}

func TestMuxOpenAcceptServerSide(t *testing.T) {
	client, server := pipePair(t, nil)
	defer closePair(t, client, server)

	// Server opens a stream to client
	var (
		sst *MuxStream
		cst *MuxStream
		wg  sync.WaitGroup
	)

	wg.Add(1)
	go func() {
		defer wg.Done()
		var err error
		sst, err = server.OpenStream(MuxPriorityHigh)
		if err != nil {
