	}()
	wg.Wait()

	if cst == nil || sst == nil {
		t.Fatal("streams should not be nil")
	}

	id := cst.ID()

	// Both sides should have the stream
	if n := client.NumStreams(); n != 1 {
		t.Errorf("client NumStreams = %d, want 1", n)
	}
	if n := server.NumStreams(); n != 1 {
		t.Errorf("server NumStreams = %d, want 1", n)
	}

	// Send data, then close both sides
	msg := []byte("drain test")
	done := make(chan struct{})
	go func() {
		cst.Write(msg)
		cst.Close()
		close(done)
	}()

	// Server reads data and closes
	buf := make([]byte, 4096)
	sst.Read(buf)
	sst.Close()

	<-done

	// Give time for stream removal
	time.Sleep(50 * time.Millisecond)

	// Stream should be removed from both sides
	client.mu.Lock()
	_, clientExists := client.streams[id]
	client.mu.Unlock()
	if clientExists {
		t.Error("client stream should be removed after both sides closed and drained")
	}

	server.mu.Lock()
	_, serverExists := server.streams[id]
	server.mu.Unlock()
	if serverExists {
		t.Error("server stream should be removed after both sides closed and drained")
	}
}

