// recordingConn wraps a net.Conn and records the frame types written in order.
type recordingConn struct {
	net.Conn
	mu     sync.Mutex
	types  []byte // frame types in write order
}

func (c *recordingConn) Write(b []byte) (int, error) {
	c.mu.Lock()
	if len(b) > 0 {
		c.types = append(c.types, b[0])
	}
	c.mu.Unlock()
	return c.Conn.Write(b)
}

func TestMuxPriorityOrdering(t *testing.T) {
	// C029: queue low-priority data then high-priority data on separate streams,
	// verify high-priority data frame arrives first on the wire.
	c, s := net.Pipe()
	rc := &recordingConn{Conn: c}

	clientCfg := DefaultMuxConfig()
	clientCfg.Side = MuxSideClient
	clientCfg.MaxFrameSize = 64 // small frames so many data frames

	serverCfg := DefaultMuxConfig()
	serverCfg.Side = MuxSideServer
	serverCfg.MaxFrameSize = 64

	client, err := NewMuxSession(rc, &clientCfg)
	if err != nil {
		t.Fatal("NewMuxSession(client):", err)
	}
	server, err := NewMuxSession(s, &serverCfg)
	if err != nil {
		t.Fatal("NewMuxSession(server):", err)
	}
	defer closePair(t, client, server)

	var (
		lowSt  *MuxStream
		highSt *MuxStream
		srvLow *MuxStream
		srvHi  *MuxStream
		wg     sync.WaitGroup
	)

	wg.Add(1)
	go func() {
		defer wg.Done()
		lowSt, _ = client.OpenStream(MuxPriorityLow)
	}()
	wg.Add(1)
	go func() {
		defer wg.Done()
		srvLow, _ = server.AcceptStream()
	}()
	wg.Wait()

	wg.Add(1)
	go func() {
		defer wg.Done()
		highSt, _ = client.OpenStream(MuxPriorityHigh)
	}()
	wg.Add(1)
	go func() {
		defer wg.Done()
		srvHi, _ = server.AcceptStream()
	}()
	wg.Wait()

	if lowSt == nil || highSt == nil || srvLow == nil || srvHi == nil {
		t.Fatal("streams should not be nil")
	}

	// Write low priority first (blocks until dispatched), then high priority
	lowMsg := []byte("low priority data")
	highMsg := []byte("high priority data")

	// Submit low-priority write
	lowDone := make(chan struct{})
	go func() {
		n, err := lowSt.Write(lowMsg)
		if err != nil {
			t.Error("lowSt.Write:", err)
		}
		if n != len(lowMsg) {
			t.Errorf("low short write: %d != %d", n, len(lowMsg))
		}
		close(lowDone)
	}()

	// Give time for the low-priority write to be queued
	time.Sleep(5 * time.Millisecond)

	// Submit high-priority write
	highDone := make(chan struct{})
	go func() {
		n, err := highSt.Write(highMsg)
		if err != nil {
			t.Error("highSt.Write:", err)
		}
		if n != len(highMsg) {
			t.Errorf("high short write: %d != %d", n, len(highMsg))
		}
		close(highDone)
	}()

	<-lowDone
	<-highDone

	// Now verify frame write order: the high-priority data frames should appear
	// before low-priority data frames on the wire.
	rc.mu.Lock()
	types := make([]byte, len(rc.types))
	copy(types, rc.types)
	rc.mu.Unlock()

	// Find the first data frame for each stream
	var firstHighData, firstLowData int = -1, -1
	for i, typ := range types {
		if typ == frameData {
			if firstHighData == -1 {
				firstHighData = i
			} else if firstLowData == -1 && firstHighData != -1 {
				firstLowData = i
				break
			}
		}
	}

	if firstHighData == -1 || firstLowData == -1 {
		t.Fatal("could not find data frames in trace")
	}

	// The first data frame should be from the high-priority stream
	if firstHighData >= firstLowData {
		t.Errorf("high-priority data frame at position %d should come before low-priority at %d",
			firstHighData, firstLowData)
	}

	// Read on server to drain
	buf := make([]byte, 4096)
	srvHi.Read(buf)
	srvLow.Read(buf)

	_ = srvLow
	_ = srvHi
}

func TestMuxControlFramePriority(t *testing.T) {
	// C030: same-priority data and control frames queued together,
	// verify control frames are written before data frames.
	c, s := net.Pipe()
	rc := &recordingConn{Conn: c}

	clientCfg := DefaultMuxConfig()
	clientCfg.Side = MuxSideClient
	clientCfg.MaxFrameSize = 64

	serverCfg := DefaultMuxConfig()
	serverCfg.Side = MuxSideServer
	serverCfg.MaxFrameSize = 64

	client, err := NewMuxSession(rc, &clientCfg)
	if err != nil {
		t.Fatal("NewMuxSession(client):", err)
	}
	server, err := NewMuxSession(s, &serverCfg)
	if err != nil {
		t.Fatal("NewMuxSession(server):", err)
	}
	defer closePair(t, client, server)

	var (
		st   *MuxStream
		sst  *MuxStream
		wg   sync.WaitGroup
	)

	wg.Add(1)
	go func() {
		defer wg.Done()
		st, _ = client.OpenStream(MuxPriorityNormal)
	}()
	wg.Add(1)
	go func() {
		defer wg.Done()
		sst, _ = server.AcceptStream()
	}()
	wg.Wait()

	// Write some data and then close the stream. The close frame (control)
	// should be written before any subsequent data frames from the same
	// stream at the same priority level.
	msg := []byte("data before close")
	done := make(chan struct{})
	go func() {
		st.Write(msg)
		st.Close()
		close(done)
	}()

	<-done

	// Check the frame trace: the close frame should appear before any
	// additional data frames that were queued after it.
	rc.mu.Lock()
	types := make([]byte, len(rc.types))
	copy(types, rc.types)
	rc.mu.Unlock()

	// Find close frame position and last data frame before close
	closePos := -1
	for i := len(types) - 1; i >= 0; i-- {
		if types[i] == frameClose {
			closePos = i
			break
		}
	}

	if closePos == -1 {
		t.Fatal("close frame not found in trace")
	}

	// All data frames sent before the close frame are fine. The close
	// should be sent promptly (no unbounded data frames after it).
	lastDataBeforeClose := -1
	for i := closePos - 1; i >= 0; i-- {
		if types[i] == frameData {
			lastDataBeforeClose = i
			break
		}
	}

	// If there's a data frame after close, that's wrong
	for i := closePos + 1; i < len(types); i++ {
		if types[i] == frameData {
			t.Errorf("data frame at position %d after close frame at %d", i, closePos)
			break
		}
	}

	// Drain server
	buf := make([]byte, 4096)
	sst.Read(buf)
	_, err = sst.Read(buf) // should get EOF
	if err != io.EOF {
		t.Logf("expected EOF after close, got %v", err)
	}

	_ = lastDataBeforeClose
}

func TestMuxSnmpDataBytesOnly(t *testing.T) {
	// C056/C057: MuxBytesSent/Received count only data payload, not control frames.
	DefaultSnmp.Reset()

	c, s := net.Pipe()

	clientCfg := DefaultMuxConfig()
	clientCfg.Side = MuxSideClient

	serverCfg := DefaultMuxConfig()
	serverCfg.Side = MuxSideServer

	client, err := NewMuxSession(c, &clientCfg)
	if err != nil {
		t.Fatal("NewMuxSession(client):", err)
	}
	server, err := NewMuxSession(s, &serverCfg)
	if err != nil {
		t.Fatal("NewMuxSession(server):", err)
	}
	defer closePair(t, client, server)

	var (
		st  *MuxStream
		sst *MuxStream
		wg  sync.WaitGroup
	)

	wg.Add(1)
	go func() {
		defer wg.Done()
		st, _ = client.OpenStream(MuxPriorityNormal)
	}()
	wg.Add(1)
	go func() {
		defer wg.Done()
		sst, _ = server.AcceptStream()
	}()
	wg.Wait()

	// Record counters before data
	sentBefore := atomic.LoadUint64(&DefaultSnmp.MuxBytesSent)
	recvBefore := atomic.LoadUint64(&DefaultSnmp.MuxBytesReceived)
	framesBefore := atomic.LoadUint64(&DefaultSnmp.MuxFramesSent)

	// Send data
	msg := []byte("payload bytes only")
	done := make(chan struct{})
	go func() {
		st.Write(msg)
		close(done)
	}()

	buf := make([]byte, 4096)
	n, err := sst.Read(buf)
	if err != nil {
		t.Fatal("sst.Read:", err)
	}
	if n != len(msg) {
		t.Fatalf("read %d bytes, expected %d", n, len(msg))
	}
	<-done

	sentAfter := atomic.LoadUint64(&DefaultSnmp.MuxBytesSent)
	recvAfter := atomic.LoadUint64(&DefaultSnmp.MuxBytesReceived)
	framesAfter := atomic.LoadUint64(&DefaultSnmp.MuxFramesSent)

	dataBytes := uint64(len(msg))
	if sentAfter-sentBefore != dataBytes {
		t.Errorf("MuxBytesSent increased by %d, want %d (data payload only)",
			sentAfter-sentBefore, dataBytes)
	}
	if recvAfter-recvBefore != dataBytes {
		t.Errorf("MuxBytesReceived increased by %d, want %d (data payload only)",
			recvAfter-recvBefore, dataBytes)
	}

	// Close the stream (control frame) and verify bytes counters don't change
	beforeCloseSent := atomic.LoadUint64(&DefaultSnmp.MuxBytesSent)
	beforeCloseRecv := atomic.LoadUint64(&DefaultSnmp.MuxBytesReceived)

	st.Close()

	if n := atomic.LoadUint64(&DefaultSnmp.MuxBytesSent); n != beforeCloseSent {
		t.Errorf("MuxBytesSent changed after close: %d -> %d", beforeCloseSent, n)
	}
	if n := atomic.LoadUint64(&DefaultSnmp.MuxBytesReceived); n != beforeCloseRecv {
		t.Errorf("MuxBytesReceived changed after close: %d -> %d", beforeCloseRecv, n)
	}

	// But frames counters should have increased
	if atomic.LoadUint64(&DefaultSnmp.MuxFramesSent) <= framesAfter {
		t.Error("MuxFramesSent should have increased after close")
	}

	_ = sst
}

func TestMuxConcurrentStreamsFlowControl(t *testing.T) {
	// C028: stream A with small send window, stream B with normal window.
	// Both write concurrently; both should complete.
	cfg := DefaultMuxConfig()
	cfg.SendWindow = 100 // tiny for stream A
	cfg.RecvWindow = 65536

	client, server := pipePair(t, &cfg)
	defer closePair(t, client, server)

	var (
		stA, stB    *MuxStream
		sstA, sstB  *MuxStream
		wg          sync.WaitGroup
	)

	wg.Add(1)
	go func() {
		defer wg.Done()
		stA, _ = client.OpenStream(MuxPriorityNormal)
	}()
	wg.Add(1)
	go func() {
		defer wg.Done()
		sstA, _ = server.AcceptStream()
	}()
	wg.Wait()

	wg.Add(1)
	go func() {
		defer wg.Done()
		stB, _ = client.OpenStream(MuxPriorityNormal)
	}()
	wg.Add(1)
	go func() {
		defer wg.Done()
		sstB, _ = server.AcceptStream()
	}()
	wg.Wait()

	if stA == nil || stB == nil || sstA == nil || sstB == nil {
		t.Fatal("streams should not be nil")
	}

	// Write 300 bytes to stream A (exhausts its 100-byte send window)
	// and 300 bytes to stream B concurrently.
	msgA := make([]byte, 300)
	for i := range msgA {
		msgA[i] = 'A'
	}
	msgB := make([]byte, 300)
	for i := range msgB {
		msgB[i] = 'B'
	}

	var errA, errB error
	var nA, nB int

	var writeWg sync.WaitGroup
	writeWg.Add(1)
	go func() {
		defer writeWg.Done()
		nA, errA = stA.Write(msgA)
	}()
	writeWg.Add(1)
	go func() {
		defer writeWg.Done()
		nB, errB = stB.Write(msgB)
	}()

	// Drain both streams on server
	buf := make([]byte, 4096)
	totalA := 0
	for totalA < len(msgA) {
		n, err := sstA.Read(buf)
		if err != nil {
			t.Fatal("sstA.Read:", err)
		}
		totalA += n
	}
	totalB := 0
	for totalB < len(msgB) {
		n, err := sstB.Read(buf)
		if err != nil {
			t.Fatal("sstB.Read:", err)
		}
		totalB += n
	}

	writeWg.Wait()

	if errA != nil {
		t.Errorf("stA.Write: %v", errA)
	}
	if errB != nil {
		t.Errorf("stB.Write: %v", errB)
	}
	if nA != len(msgA) {
		t.Errorf("stA short write: %d != %d", nA, len(msgA))
	}
