    // We need to be careful: world entity is ctx.worldEntity
    const entitiesToDestroy = world.entities.filter(
        (e) => e !== ctx.worldEntity
    );
    for (const entity of entitiesToDestroy) {
        destroyEntity(world, entity);
    }

    // Now rebuild the entity index so we can allocate specific IDs.
    // After destroying all non-world entities, the entity index has:
    // - dense array containing all entities (world + destroyed), aliveCount = 1
    // - maxId might be high from previous allocations
    // We need to reset and allocate entities with the exact checkpoint IDs.

    // Strategy: reset the entity index to start fresh, allocate world entity (ID 0),
    // then allocate checkpoint entities with exact IDs by directly manipulating the index.

    // First, reset the entity index completely
    const entityIndex = ctx.entityIndex;

    // Clear entity traits map for all non-world entities
    // The world entity's traits need to be preserved
    // Actually, the world entity was in the destruction list too!
    // No, we filtered it out. The world entity is still alive.
    const worldEntity = ctx.worldEntity;
    const worldEntityTraits = ctx.entityTraits.get(worldEntity);

    // Destroy the world entity too - we need a clean slate
    destroyEntity(world, worldEntity);

    // Now all entities are destroyed. Reset the entity index.
    entityIndex.sparse.length = 0;
    entityIndex.dense.splice(0, entityIndex.dense.length);
    entityIndex.aliveCount = 0;
    entityIndex.maxId = 0;
    ctx.entityTraits.clear();

    // Clear entity masks for the new allocation
    // We need to reinitialize the entity masks
    const numMasks = ctx.entityMasks.length;
    for (let i = 0; i < numMasks; i++) {
        ctx.entityMasks[i] = [];
    }

