    // We need to create entities with ID 0 (world entity), then the checkpoint IDs.
    // But entity IDs need to be allocated sequentially from the index.
    // We'll manually manipulate the index to assign specific IDs.

    // Helper to allocate an entity with a specific ID
    function allocateWithId(id: number): Entity {
        const generation = 0;
        const entity = packEntity(entityIndex.worldId, generation, id);
        const denseIdx = entityIndex.aliveCount;

        // Ensure sparse array is large enough
        if (id >= entityIndex.sparse.length) {
            entityIndex.sparse.length = id + 1;
        }

        // If dense array is already long enough, update in place
        if (denseIdx < entityIndex.dense.length) {
            entityIndex.dense[denseIdx] = entity;
        } else {
            entityIndex.dense.push(entity);
        }

        entityIndex.sparse[id] = denseIdx;
        entityIndex.aliveCount++;
        if (id >= entityIndex.maxId) {
            entityIndex.maxId = id + 1;
        }

        return entity;
    }

    // Allocate world entity (ID 0)
    const newWorldEntity = allocateWithId(0);
    ctx.worldEntity = newWorldEntity;

    // Initialize entity traits map entry for world entity
    ctx.entityTraits.set(newWorldEntity, new Set());

    // Re-register IsExcluded trait on the world entity (it was removed on destruction)
    const { IsExcluded } = require('../query/query');
    addTrait(world, newWorldEntity, IsExcluded);

    // Restore world entity traits if any were on it (from original snapshot)
    // The world entity's traits are not in the checkpoint, but they were on the
    // original world entity. We don't restore them since the checkpoint is for
    // user entities only.

    // Allocate checkpoint entities with exact IDs
    const idToPacked = new Map<number, Entity>();
    idToPacked.set(0, newWorldEntity);

    for (const es of checkpoint.entities) {
        const entity = allocateWithId(es.id);
        idToPacked.set(es.id, entity);
        ctx.entityTraits.set(entity, new Set());
    }

    // Now set up traits and relations on each entity
    for (const es of checkpoint.entities) {
        const entity = idToPacked.get(es.id)!;

        // Add traits
        for (const [traitName, traitValue] of Object.entries(es.traits)) {
            const entry = registry.byName.get(traitName)!;

            if (traitValue === true) {
                addTrait(world, entity, entry.trait);
            } else {
                addTrait(world, entity, entry.trait);
                setTrait(world, entity, entry.trait, { ...(traitValue as object) }, false);
            }
        }

        // Add relations
        if (es.relations) {
            for (const [relationName, targets] of Object.entries(es.relations)) {
                const entry = registry.byName.get(relationName)!;
                const relation = entry.relation!;

                for (const rel of targets) {
                    const targetEntity = idToPacked.get(rel.targetId);
                    if (!targetEntity) {
                        throw new Error(
                            `Snapshot: Relation target entity ${rel.targetId} does not exist in checkpoint`
                        );
                    }

                    // Ensure base trait exists
                    if (!hasTrait(world, entity, entry.trait)) {
                        addTrait(world, entity, entry.trait);
                    }

                    addRelationTarget(world, relation, entity, targetEntity);

                    if (rel.data && Object.keys(rel.data).length > 0) {
                        const targetIndex = getTargetIndexForTarget(
                            world,
                            relation,
                            entity,
                            targetEntity
                        );
                        if (targetIndex !== -1) {
                            setRelationDataAtIndex(
                                world,
                                entity,
                                relation,
                                targetIndex,
                                rel.data as Record<string, unknown>
                            );
                        }
                    }
                }
            }
        }
    }
}
