        throw new Error('Snapshot: diffEntitySnapshots requires non-null arguments');
    }

    const addedTraits: string[] = [];
    const removedTraits: string[] = [];
    const changedTraits: string[] = [];

    const allKeys = new Set([...Object.keys(a.traits), ...Object.keys(b.traits)]);

    for (const key of allKeys) {
        const hasA = key in a.traits;
        const hasB = key in b.traits;

        if (!hasA && hasB) {
            addedTraits.push(key);
        } else if (hasA && !hasB) {
            removedTraits.push(key);
        } else {
            const valA = a.traits[key];
            const valB = b.traits[key];

            if (!shallowEqual(valA, valB)) {
                changedTraits.push(key);
            }
        }
    }

    addedTraits.sort();
    removedTraits.sort();
    changedTraits.sort();

    return { addedTraits, removedTraits, changedTraits };
}

/**
 * Normalizes an entity snapshot for comparison by sorting keys and ensuring
 * consistent representation of empty relations.
 */
function normalizeEntityForDiff(es: EntitySnapshot): EntitySnapshot {
    const traits: Record<string, object | true> = {};
    const sortedTraitKeys = Object.keys(es.traits).sort();
    for (const key of sortedTraitKeys) {
        traits[key] = es.traits[key];
    }

    let relations: Record<string, Array<{ targetId: number; data?: object }>> | undefined;

    if (es.relations && Object.keys(es.relations).length > 0) {
        relations = {};
        const sortedRelationKeys = Object.keys(es.relations).sort();
        for (const key of sortedRelationKeys) {
            const targets = [...es.relations[key]];
            targets.sort((a, b) => a.targetId - b.targetId);
            relations[key] = targets;
        }
    }

    return { id: es.id, traits, ...(relations !== undefined ? { relations } : {}) };
}

/**
 * Compares two normalized entity snapshots for equality.
 * Trait and relation data is compared shallowly.
 */
function entitySnapshotsEqual(a: EntitySnapshot, b: EntitySnapshot): boolean {
    if (a.id !== b.id) return false;

    // Compare traits
    const aTraitKeys = Object.keys(a.traits).sort();
    const bTraitKeys = Object.keys(b.traits).sort();
    if (!shallowEqual(aTraitKeys, bTraitKeys)) return false;

    for (const key of aTraitKeys) {
        if (!shallowEqual(a.traits[key], b.traits[key])) return false;
    }

    // Compare relations - treat {} or undefined as equivalent (both empty)
    const aRelKeys = a.relations ? Object.keys(a.relations) : [];
    const bRelKeys = b.relations ? Object.keys(b.relations) : [];

    if (aRelKeys.length === 0 && bRelKeys.length === 0) return true;
    if (aRelKeys.length !== bRelKeys.length) return false;

    const sortedARelKeys = [...aRelKeys].sort();
    const sortedBRelKeys = [...bRelKeys].sort();
    if (!shallowEqual(sortedARelKeys, sortedBRelKeys)) return false;

    for (const key of sortedARelKeys) {
        const aTargets = a.relations![key];
        const bTargets = b.relations![key];

        if (aTargets.length !== bTargets.length) return false;

        // Sort both by targetId for comparison
        const sortedA = [...aTargets].sort((x, y) => x.targetId - y.targetId);
        const sortedB = [...bTargets].sort((x, y) => x.targetId - y.targetId);

        for (let i = 0; i < sortedA.length; i++) {
            if (sortedA[i].targetId !== sortedB[i].targetId) return false;
            if (!shallowEqual(sortedA[i].data, sortedB[i].data)) return false;
        }
    }

    return true;
}

/**
 * Computes the diff between two world snapshots.
 *
 * Entities are matched by ID. Trait key ordering, relation key ordering,
 * and relation target ordering do not affect equality. Trait and relation
 * data is compared shallowly. An entity with `relations: {}` is equivalent
 * to one with no `relations` key.
 *
 * @param before - The first world snapshot
 * @param after - The second world snapshot
 * @returns A WorldDiff with sorted added, removed, and changed entity IDs
 * @throws Error if either argument is null, undefined, or lacks an entities array
 */
export function diffWorldSnapshots(
    before: WorldSnapshot | null | undefined,
    after: WorldSnapshot | null | undefined
): WorldDiff {
    if (before == null || after == null) {
        throw new Error('Snapshot: diffWorldSnapshots requires non-null arguments');
    }
    if (!Array.isArray(before.entities) || !Array.isArray(after.entities)) {
        throw new Error('Snapshot: diffWorldSnapshots requires snapshots with entities arrays');
    }

    const beforeMap = new Map<number, EntitySnapshot>();
    const afterMap = new Map<number, EntitySnapshot>();

    for (const es of before.entities) {
        beforeMap.set(es.id, es);
    }
    for (const es of after.entities) {
        afterMap.set(es.id, es);
    }

    const allIds = new Set([...beforeMap.keys(), ...afterMap.keys()]);
    const added: number[] = [];
    const removed: number[] = [];
    const changed: number[] = [];

    for (const id of allIds) {
        const inBefore = beforeMap.has(id);
        const inAfter = afterMap.has(id);

        if (!inBefore && inAfter) {
            added.push(id);
        } else if (inBefore && !inAfter) {
            removed.push(id);
        } else {
            const beforeEntity = beforeMap.get(id)!;
            const afterEntity = afterMap.get(id)!;
            if (!entitySnapshotsEqual(beforeEntity, afterEntity)) {
                changed.push(id);
            }
        }
    }

    added.sort((a, b) => a - b);
    removed.sort((a, b) => a - b);
    changed.sort((a, b) => a - b);

    return { added, removed, changed };
}
"}

