{"file_path": "packages/core/src/snapshot/rollback.ts", "content": "import { $internal } from '../common';
import type { Entity } from '../entity/types';
import { destroyEntity } from '../entity/entity';
import { getEntityId, packEntity } from '../entity/utils/pack-entity';
import { isEntityAlive } from '../entity/utils/entity-index';
import { IsExcluded } from '../query/query';
import {
    addRelationTarget,
    getRelationTargets,
    hasRelationToTarget,
    removeRelationTarget,
    setRelationDataAtIndex,
} from '../relation/relation';
import type { Relation } from '../relation/types';
import { addTrait, hasTrait, removeTrait, setTrait } from '../trait/trait';
import type { Trait } from '../trait/types';
import type { World } from '../world/types';
import type { EntitySnapshot, RegistryEntry, TraitRegistry, WorldSnapshot } from './types';

function getTargetIndexForTarget(
    world: World,
    relation: Relation,
    entity: Entity,
    target: Entity
): number {
    const targets = getRelationTargets(world, relation, entity) as readonly Entity[];
    return targets.indexOf(target);
}

/**
 * Rolls back a single entity to match a snapshot.
 *
 * Removes traits/relations not in the snapshot, then adds/updates
 * traits and relations to match the snapshot exactly.
 *
 * @param world - The world containing the entity
 * @param entity - The entity to roll back
 * @param registry - A trait registry mapping names to traits/relations
 * @param snapshot - The target snapshot to restore
 * @throws Error if a relation target entity does not exist in the world
 * @throws Error if the entity is destroyed
 * @throws Error if a registry key in the snapshot is unknown
 */
export function rollbackEntity(
    world: World,
    entity: Entity,
    registry: TraitRegistry,
    snapshot: EntitySnapshot
): void {
    const ctx = world[$internal];

    if (!isEntityAlive(ctx.entityIndex, entity)) {
        throw new Error('Snapshot: Cannot rollback destroyed entity');
    }

    // Validate all registry keys in snapshot first
    for (const traitName of Object.keys(snapshot.traits)) {
        if (!registry.byName.has(traitName)) {
            throw new Error(`Snapshot: Unknown registry key "${traitName}" in snapshot`);
        }
    }
    if (snapshot.relations) {
        for (const relationName of Object.keys(snapshot.relations)) {
            if (!registry.byName.has(relationName)) {
                throw new Error(`Snapshot: Unknown registry key "${relationName}" in snapshot`);
            }
        }
    }

    // Validate relation target entities exist in the world
    if (snapshot.relations) {
        for (const targets of Object.values(snapshot.relations)) {
            for (const rel of targets) {
                const targetPacked = (ctx.entityIndex.dense as Entity[])
                    .slice(0, ctx.entityIndex.aliveCount)
                    .find(
                        (e) =>
                            getEntityId(e) === rel.targetId && isEntityAlive(ctx.entityIndex, e)
                    );
                if (!targetPacked) {
                    throw new Error(
                        `Snapshot: Relation target entity ${rel.targetId} does not exist in the world`
                    );
                }
            }
        }
    }

    const currentTraits = ctx.entityTraits.get(entity);
    if (!currentTraits) return;

    // Build a set of trait names currently on the entity (via registry lookup)
    const currentTraitNames = new Set<string>();
    for (const trait of currentTraits) {
        const entry = registry.byTraitId.get(trait.id);
        if (entry) {
            currentTraitNames.add(entry.name);
        }
    }

    // Build set of desired trait names from snapshot
    const desiredTraitNames = new Set(Object.keys(snapshot.traits));
    const desiredRelationNames = snapshot.relations
        ? new Set(Object.keys(snapshot.relations))
        : new Set<string>();

    // Combine all desired names (traits + relations)
    const allDesiredNames = new Set([...desiredTraitNames, ...desiredRelationNames]);

    // Remove traits/relations the entity has that are not desired
    for (const traitName of currentTraitNames) {
        if (!allDesiredNames.has(traitName)) {
            const entry = registry.byName.get(traitName)!;
            removeTrait(world, entity, entry.trait);
        }
    }

    // Process desired traits/relations
    for (const name of allDesiredNames) {
        const entry = registry.byName.get(name)!;

        if (entry.type === 'relation') {
            const relation = entry.relation!;
            const desiredTargets = snapshot.relations?.[name] ?? [];

            // Get current targets (re-fetch because removal may have changed the set)
            const currentTargets = getRelationTargets(world, relation, entity) as readonly Entity[];

            // Build sets of target IDs
            const desiredTargetIds = new Set(desiredTargets.map((t) => t.targetId));
            const currentTargetIds = new Set(currentTargets.map((t) => getEntityId(t)));

            // Remove targets not in snapshot
            for (const target of currentTargets) {
                const targetId = getEntityId(target);
                if (!desiredTargetIds.has(targetId)) {
                    removeRelationTarget(world, relation, entity, target);
                }
            }

            // Ensure the base trait exists
            if (!hasTrait(world, entity, entry.trait)) {
                addTrait(world, entity, entry.trait);
            }

            // Add missing targets and update data
            for (const relSnapshot of desiredTargets) {
                // Find the actual packed entity
                const targetEntity = (ctx.entityIndex.dense as Entity[])
                    .slice(0, ctx.entityIndex.aliveCount)
                    .find(
                        (e) =>
                            getEntityId(e) === relSnapshot.targetId &&
                            isEntityAlive(ctx.entityIndex, e)
                    );

                if (!targetEntity) {
                    throw new Error(
                        `Snapshot: Relation target entity ${relSnapshot.targetId} does not exist in the world`
                    );
                }

                // Add the relation if not present
                if (!hasRelationToTarget(world, relation, entity, targetEntity)) {
                    addRelationTarget(world, relation, entity, targetEntity);
                }

                // Set data if present
                if (relSnapshot.data) {
                    const targetIndex = getTargetIndexForTarget(
                        world,
                        relation,
                        entity,
                        targetEntity
                    );
                    if (targetIndex !== -1) {
                        setRelationDataAtIndex(
                            world,
                            entity,
                            relation,
                            targetIndex,
                            relSnapshot.data as Record<string, unknown>
                        );
                    }
                }
            }
        } else {
            const trait = entry.trait;
            const hasCurrent = currentTraits.has(trait);

            if (snapshot.traits[name] === true) {
                // Tag trait
                if (!hasCurrent) {
                    addTrait(world, entity, trait);
                }
            } else {
                // Data trait
                if (!hasCurrent) {
                    addTrait(world, entity, trait);
                }
                const snapshotData = snapshot.traits[name] as object;
                setTrait(world, entity, trait, { ...snapshotData }, false);
            }
        }
    }
}

/**
 * Rolls back an entire world to match a checkpoint snapshot.
 *
 * Destroys all existing entities and recreates them from the checkpoint,
 * preserving the same entity IDs.
 *
 * @param world - The world to roll back
 * @param registry - A trait registry mapping names to traits/relations
 * @param checkpoint - The target world snapshot to restore
 * @throws Error if a registry key in the checkpoint is unknown
 * @throws Error if a relation target entity does not exist
 */
export function rollbackWorld(
    world: World,
    registry: TraitRegistry,
    checkpoint: WorldSnapshot
): void {
    const ctx = world[$internal];

    // Validate all registry keys and relation targets first
    for (const entitySnapshot of checkpoint.entities) {
        for (const traitName of Object.keys(entitySnapshot.traits)) {
            if (!registry.byName.has(traitName)) {
                throw new Error(`Snapshot: Unknown registry key "${traitName}" in checkpoint`);
            }
        }
        if (entitySnapshot.relations) {
            for (const relationName of Object.keys(entitySnapshot.relations)) {
                if (!registry.byName.has(relationName)) {
                    throw new Error(
                        `Snapshot: Unknown registry key "${relationName}" in checkpoint`
                    );
                }
                const targets = entitySnapshot.relations[relationName];
                for (const rel of targets) {
                    const targetExists = checkpoint.entities.some(
                        (e) => e.id === rel.targetId
                    );
                    if (!targetExists) {
                        throw new Error(
                            `Snapshot: Relation target entity ${rel.targetId} does not exist in checkpoint`
                        );
                    }
                }
            }
        }
    }

    // Destroy all existing user entities
    const entitiesToDestroy = world.entities.filter((e) => e !== ctx.worldEntity);
    for (const entity of entitiesToDestroy) {
        destroyEntity(world, entity);
    }

    // Also destroy world entity - we need a clean index
    destroyEntity(world, ctx.worldEntity);

    // Reset the entity index completely
    const entityIndex = ctx.entityIndex;
    entityIndex.sparse.length = 0;
    entityIndex.dense.splice(0, entityIndex.dense.length);
    entityIndex.aliveCount = 0;
    entityIndex.maxId = 0;

    // Reinitialize entity masks
    for (let i = 0; i < ctx.entityMasks.length; i++) {
        ctx.entityMasks[i] = [];
    }

    ctx.entityTraits.clear();

    // Helper to allocate an entity with a specific ID
    function allocateWithId(id: number): Entity {
        const generation = 0;
        const entity = packEntity(entityIndex.worldId, generation, id);

        // Ensure sparse array is large enough
        if (id >= entityIndex.sparse.length) {
            entityIndex.sparse.length = id + 1;
        }

        entityIndex.sparse[id] = entityIndex.aliveCount;
        entityIndex.dense[entityIndex.aliveCount] = entity;
        entityIndex.aliveCount++;
        if (id >= entityIndex.maxId) {
            entityIndex.maxId = id + 1;
        }

        return entity;
    }

    // Allocate world entity (ID 0)
    const newWorldEntity = allocateWithId(0);
    ctx.worldEntity = newWorldEntity;
    ctx.entityTraits.set(newWorldEntity, new Set());

    // Re-register IsExcluded on the world entity (it was removed during destruction)
    addTrait(world, newWorldEntity, IsExcluded);

    // Map from entity ID to packed entity for relation target resolution
    const idToPacked = new Map<number, Entity>();
    idToPacked.set(0, newWorldEntity);

    // Allocate all checkpoint entities with exact IDs
    for (const es of checkpoint.entities) {
        const entity = allocateWithId(es.id);
        idToPacked.set(es.id, entity);
        ctx.entityTraits.set(entity, new Set());
    }

    // Now set up traits and relations on each checkpoint entity
    for (const es of checkpoint.entities) {
        const entity = idToPacked.get(es.id)!;

        for (const [traitName, traitValue] of Object.entries(es.traits)) {
            const entry = registry.byName.get(traitName)!;

            if (traitValue === true) {
                addTrait(world, entity, entry.trait);
            } else {
                addTrait(world, entity, entry.trait);
                setTrait(world, entity, entry.trait, { ...(traitValue as object) }, false);
            }
        }

        if (es.relations) {
            for (const [relationName, targets] of Object.entries(es.relations)) {
                const entry = registry.byName.get(relationName)!;
                const relation = entry.relation!;

                for (const rel of targets) {
                    const targetEntity = idToPacked.get(rel.targetId);
                    if (!targetEntity) {
                        throw new Error(
                            `Snapshot: Relation target entity ${rel.targetId} does not exist in checkpoint`
                        );
                    }

                    if (!hasTrait(world, entity, entry.trait)) {
                        addTrait(world, entity, entry.trait);
                    }

                    addRelationTarget(world, relation, entity, targetEntity);

                    if (rel.data && Object.keys(rel.data).length > 0) {
                        const targetIndex = getTargetIndexForTarget(
                            world,
                            relation,
                            entity,
                            targetEntity
                        );
                        if (targetIndex !== -1) {
                            setRelationDataAtIndex(
                                world,
                                entity,
                                relation,
                                targetIndex,
                                rel.data as Record<string, unknown>
                            );
                        }
                    }
                }
            }
        }
    }
}
"}

