{"file_path": "packages/query-core/src/__tests__/restore.test.ts", "content": "import { describe, expect, test, vi } from 'vitest'
import { QueryClient } from '../queryClient'
import { QueryObserver } from '../queryObserver'
import { QueryCache } from '../queryCache'
import { Query, createPersisterRestoreResult, mergeQueryState } from '../query'
import {
  createPersisterRestoreResult as createPersisterRestoreResult2,
  mergeQueryState as mergeQueryState2,
} from '../index'
import type { QueryState } from '../query'

// Helper to create a minimal query state
function makeState(
  overrides: Partial<QueryState> = {},
): QueryState {
  return {
    data: undefined,
    dataUpdateCount: 0,
    dataUpdatedAt: 0,
    error: null,
    errorUpdateCount: 0,
    errorUpdatedAt: 0,
    fetchFailureCount: 0,
    fetchFailureReason: null,
    fetchMeta: null,
    isInvalidated: false,
    status: 'pending',
    fetchStatus: 'idle',
    ...overrides,
  }
}

describe('createPersisterRestoreResult', () => {
  test('should return an object with data, state, and symbol brand', () => {
    const state = makeState({ data: 'cached-data', status: 'success', dataUpdatedAt: 100 })
    const result = createPersisterRestoreResult({ data: 'cached-data', state })

    expect(result).toEqual({
      data: 'cached-data',
      state,
      [Symbol.for('persisterRestoreResult') as unknown as string]: true,
    })
    // The symbol should be present
    const SymbolKey = Object.getOwnPropertySymbols(result).find(
      (s) => s.description === 'persisterRestoreResult',
    )
    expect(SymbolKey).toBeDefined()
    expect((result as any)[SymbolKey!]).toBe(true)
  })

  test('should be exported from index', () => {
    expect(createPersisterRestoreResult2).toBe(createPersisterRestoreResult)
  })
})

describe('Query.fetch - persister restore result', () => {
  test('should adopt provided state when persister returns a restore result', async () => {
    const client = new QueryClient()
    const queryCache = client.getQueryCache()

    const persistedState = makeState({
      data: 'restored-data',
      dataUpdatedAt: 500,
      dataUpdateCount: 3,
      status: 'success',
      isInvalidated: true,
    })

    const query = new Query({
      client,
      queryHash: '["test-key"]',
      queryKey: ['test-key'],
    })

    // Override fetch to simulate a persister that returns a restore result
    query.fetch = vi.fn().mockImplementation(async function (this: Query) {
      this.setState({
        ...persistedState,
        fetchStatus: 'idle' as const,
      })
      return 'restored-data'
    })

    const result = await query.fetch()
    expect(result).toBe('restored-data')

    // The query state should reflect the persisted state
    expect(query.state.data).toBe('restored-data')
    expect(query.state.dataUpdatedAt).toBe(500)
    expect(query.state.dataUpdateCount).toBe(3)
    expect(query.state.status).toBe('success')
    expect(query.state.isInvalidated).toBe(true)
    expect(query.state.fetchStatus).toBe('idle')
  })

  test('should preserve error state from persisted snapshot', async () => {
    const client = new QueryClient()
    const queryCache = client.getQueryCache()

    const persistedError = new Error('persisted-error')
    const persistedState = makeState({
      data: undefined,
      error: persistedError,
      errorUpdatedAt: 1000,
      errorUpdateCount: 2,
      fetchFailureCount: 3,
      fetchFailureReason: persistedError,
      status: 'error',
    })

    const query = new Query({
      client,
      queryHash: '["error-key"]',
      queryKey: ['error-key'],
    })

    // Simulate persister restore setting the error state
    query.setState(persistedState)

    expect(query.state.error).toBe(persistedError)
    expect(query.state.errorUpdatedAt).toBe(1000)
    expect(query.state.errorUpdateCount).toBe(2)
    expect(query.state.fetchFailureCount).toBe(3)
    expect(query.state.fetchFailureReason).toBe(persistedError)
    expect(query.state.status).toBe('error')
    expect(query.state.data).toBeUndefined()
  })

  test('should produce refetch-error state when data and error are both present', () => {
    const client = new QueryClient()

    const persistedError = new Error('refetch-error')
    const state = makeState({
      data: 'some-data',
      error: persistedError,
      errorUpdatedAt: 500,
      dataUpdatedAt: 200,
      status: 'error',
      fetchFailureCount: 2,
      fetchFailureReason: persistedError,
    })

    const query = new Query({
      client,
      queryHash: '["refetch-error-key"]',
      queryKey: ['refetch-error-key'],
    })

    query.setState(state)

    // Both data and error present
    expect(query.state.data).toBe('some-data')
    expect(query.state.error).toBe(persistedError)
    expect(query.state.status).toBe('error')

    // Observer result should reflect isRefetchError
    const observer = new QueryObserver(client, {
      queryKey: ['refetch-error-key'],
    })
    const result = observer.getCurrentResult()
    expect(result.data).toBe('some-data')
    expect(result.error).toBe(persistedError)
    expect(result.isError).toBe(true)
    expect(result.isRefetchError).toBe(true)
    expect(result.status).toBe('error')
  })

  test('should preserve failure counters and timestamps', async () => {
    const client = new QueryClient()

    const persistedState = makeState({
      data: 'data-with-failures',
      dataUpdatedAt: 100,
      error: new Error('previous-error'),
      errorUpdatedAt: 300,
      errorUpdateCount: 5,
      fetchFailureCount: 4,
      fetchFailureReason: new Error('previous-error'),
      status: 'error',
    })

    const query = new Query({
      client,
      queryHash: '["failure-counters"]',
      queryKey: ['failure-counters'],
    })

    query.setState(persistedState)

    expect(query.state.fetchFailureCount).toBe(4)
    expect(query.state.errorUpdateCount).toBe(5)
    expect(query.state.errorUpdatedAt).toBe(300)
    expect(query.state.dataUpdatedAt).toBe(100)
    expect(query.state.fetchFailureReason?.message).toBe('previous-error')
  })

  test('should restore correctly through the full fetch flow with a persister', async () => {
    const client = new QueryClient()
    const onSuccess = vi.fn()
    const onSettled = vi.fn()
    const onError = vi.fn()
    client.getQueryCache().config.onSuccess = onSuccess
    client.getQueryCache().config.onSettled = onSettled
    client.getQueryCache().config.onError = onError

    const persistedState = makeState({
      data: 'persisted',
      dataUpdatedAt: 200,
      dataUpdateCount: 1,
      status: 'success',
      fetchFailureCount: 0,
      error: null,
    })

    // A query that uses a persister which returns a restore result
    const queryHash = '["restore-flow-key"]'
    const queryKey = ['restore-flow-key'] as const
    const query = new Query({
      client,
      queryHash,
      queryKey,
      options: {
        queryKey,
        persister: () => {
          return Promise.resolve(
            createPersisterRestoreResult({
              data: 'persisted',
              state: persistedState,
            }),
          )
        },
        queryFn: () => 'fresh-data',
      },
    })

    const result = await query.fetch()
    expect(result).toBe('persisted')

    // onSuccess should NOT be called since this is a restore, not a fresh fetch
    expect(onSuccess).not.toHaveBeenCalled()
    expect(onSettled).not.toHaveBeenCalled()
    expect(onError).not.toHaveBeenCalled()

    // The query state should reflect the persisted snapshot
    expect(query.state.data).toBe('persisted')
    expect(query.state.dataUpdatedAt).toBe(200)
    expect(query.state.fetchStatus).toBe('idle')
  })
})

describe('mergeQueryState', () => {
  test('should keep newer data when persisted data is newer', () => {
    const existing = makeState({
      data: 'old-data',
      dataUpdatedAt: 100,
      status: 'success',
    })
    const persisted = makeState({
      data: 'new-data',
      dataUpdatedAt: 200,
      status: 'success',
    })

    const merged = mergeQueryState(existing, persisted)
    expect(merged.data).toBe('new-data')
    expect(merged.dataUpdatedAt).toBe(200)
  })

  test('should keep older data when existing data is newer', () => {
    const existing = makeState({
      data: 'new-data',
      dataUpdatedAt: 200,
      status: 'success',
    })
    const persisted = makeState({
      data: 'old-data',
      dataUpdatedAt: 100,
      status: 'success',
    })

    const merged = mergeQueryState(existing, persisted)
    expect(merged.data).toBe('new-data')
    expect(merged.dataUpdatedAt).toBe(200)
  })

  test('should keep newer error when persisted error is newer', () => {
    const existing = makeState({
      data: 'data',
      dataUpdatedAt: 100,
      error: null,
      errorUpdatedAt: 0,
      status: 'success',
    })
    const persisted = makeState({
      data: 'data',
      dataUpdatedAt: 100,
      error: new Error('newer-error'),
      errorUpdatedAt: 300,
      fetchFailureCount: 2,
      fetchFailureReason: new Error('newer-error'),
      status: 'error',
    })

    const merged = mergeQueryState(existing, persisted)
    expect(merged.error?.message).toBe('newer-error')
    expect(merged.errorUpdatedAt).toBe(300)
    expect(merged.fetchFailureCount).toBe(2)
    // Data from existing (same timestamp) should be kept
    expect(merged.data).toBe('data')
  })

  test('should independently merge data and error freshness', () => {
    // Existing has newer data, persisted has newer error
    const existing = makeState({
      data: 'newer-data',
      dataUpdatedAt: 500,
      error: null,
      errorUpdatedAt: 0,
      status: 'success',
    })
    const persisted = makeState({
      data: 'older-data',
      dataUpdatedAt: 100,
      error: new Error('newer-error'),
      errorUpdatedAt: 400,
      fetchFailureCount: 1,
      fetchFailureReason: new Error('newer-error'),
      status: 'error',
    })

    const merged = mergeQueryState(existing, persisted)
    // Data should come from existing (newer)
    expect(merged.data).toBe('newer-data')
    expect(merged.dataUpdatedAt).toBe(500)
    // Error should come from persisted (newer)
    expect(merged.error?.message).toBe('newer-error')
    expect(merged.errorUpdatedAt).toBe(400)
    expect(merged.fetchFailureCount).toBe(1)
    // Result should be refetch-error (data + error)
    expect(merged.status).toBe('error')
  })

  test('should independently merge: newer data from persisted, newer error from existing', () => {
    const existing = makeState({
      data: 'older-data',
      dataUpdatedAt: 100,
      error: new Error('newer-error'),
      errorUpdatedAt: 400,
      fetchFailureCount: 3,
      fetchFailureReason: new Error('newer-error'),
      status: 'error',
    })
    const persisted = makeState({
      data: 'newer-data',
      dataUpdatedAt: 500,
      error: null,
      errorUpdatedAt: 0,
      status: 'success',
    })

    const merged = mergeQueryState(existing, persisted)
    // Data should come from persisted (newer)
    expect(merged.data).toBe('newer-data')
    expect(merged.dataUpdatedAt).toBe(500)
    // Error should come from existing (newer)
    expect(merged.error?.message).toBe('newer-error')
    expect(merged.errorUpdatedAt).toBe(400)
    // Status should be refetch-error since both data and error are present
    expect(merged.status).toBe('error')
  })

  test('should not retain error metadata when existing has newer timestamps but no error', () => {
    const existing = makeState({
      data: 'data',
      dataUpdatedAt: 300,
      error: null,
      errorUpdatedAt: 0,
      status: 'success',
    })
    const persisted = makeState({
      data: 'data',
      dataUpdatedAt: 200,
      error: new Error('old-error'),
      errorUpdatedAt: 100,
      fetchFailureCount: 1,
      fetchFailureReason: new Error('old-error'),
      status: 'error',
    })

    const merged = mergeQueryState(existing, persisted)
    // Error from persisted is older than existing errorUpdatedAt (0 vs 100)
    // but existing error is null at errorUpdatedAt=0, so we persist the newer error (100)
    expect(merged.error?.message).toBe('old-error')
    expect(merged.errorUpdatedAt).toBe(100)
    // Data from existing should win
    expect(merged.data).toBe('data')
    expect(merged.dataUpdatedAt).toBe(300)
  })

  test('should be exported from index', () => {
    expect(mergeQueryState2).toBe(mergeQueryState)
  })
})

describe('Bulk restoration from fine-grained storage', () => {
  test('should preserve all query state fields when rebuilding cache', async () => {
    const client = new QueryClient()
    const queryCache = client.getQueryCache()

    // Simulate restoring multiple queries with full state
    const error1 = new Error('error-1')
    const error2 = new Error('error-2')

    const queries = [
      {
        queryHash: '["q1"]',
        queryKey: ['q1'] as const,
        state: makeState({
          data: 'data-1',
          dataUpdatedAt: 100,
          dataUpdateCount: 2,
          status: 'success',
        }),
      },
      {
        queryHash: '["q2"]',
        queryKey: ['q2'] as const,
        state: makeState({
          data: 'data-2',
          dataUpdatedAt: 200,
          error: error1,
          errorUpdatedAt: 150,
          errorUpdateCount: 1,
          fetchFailureCount: 1,
          fetchFailureReason: error1,
          status: 'error',
        }),
      },
      {
        queryHash: '["q3"]',
        queryKey: ['q3'] as const,
        state: makeState({
          data: undefined,
          error: error2,
          errorUpdatedAt: 300,
          errorUpdateCount: 3,
          fetchFailureCount: 3,
          fetchFailureReason: error2,
          status: 'error',
        }),
      },
    ]

    for (const q of queries) {
      queryCache.build(client, {
        queryKey: q.queryKey,
        queryHash: q.queryHash,
        queryFn: () => 'unused',
      })
    }

    // Apply persisted state to each query
    for (const q of queries) {
      const query = queryCache.get(q.queryHash)
      expect(query).toBeDefined()
      query!.setState(q.state)
    }

    // Verify each query preserves its full state

    // q1: success state
    const q1 = queryCache.get('["q1"]')!
    expect(q1.state.data).toBe('data-1')
    expect(q1.state.dataUpdatedAt).toBe(100)
    expect(q1.state.dataUpdateCount).toBe(2)
    expect(q1.state.status).toBe('success')
    expect(q1.state.error).toBeNull()

    // q2: refetch-error state (data + error)
    const q2 = queryCache.get('["q2"]')!
    expect(q2.state.data).toBe('data-2')
    expect(q2.state.dataUpdatedAt).toBe(200)
    expect(q2.state.error?.message).toBe('error-1')
    expect(q2.state.errorUpdatedAt).toBe(150)
    expect(q2.state.errorUpdateCount).toBe(1)
    expect(q2.state.fetchFailureCount).toBe(1)
    expect(q2.state.fetchFailureReason?.message).toBe('error-1')
    expect(q2.state.status).toBe('error')

    // q3: error state (no data)
    const q3 = queryCache.get('["q3"]')!
    expect(q3.state.data).toBeUndefined()
    expect(q3.state.error?.message).toBe('error-2')
    expect(q3.state.errorUpdatedAt).toBe(300)
    expect(q3.state.errorUpdateCount).toBe(3)
    expect(q3.state.fetchFailureCount).toBe(3)
    expect(q3.state.status).toBe('error')
    expect(q3.state.fetchStatus).toBe('idle')
  })

  test('should reconcile persisted snapshots with existing in-memory queries', async () => {
    const client = new QueryClient()
    const queryCache = client.getQueryCache()

    const queryHash = '["reconcile"]'
    const queryKey = ['reconcile'] as const

    // Build a query with existing state (newer data)
    const query = queryCache.build(client, {
      queryKey,
      queryHash,
      queryFn: () => 'unused',
    })
    query.setState(
      makeState({
        data: 'existing-newer-data',
        dataUpdatedAt: 500,
        status: 'success',
      }),
    )

    // Persisted snapshot has older data but newer error
    const persistedError = new Error('persisted-error')
    const persistedState = makeState({
      data: 'persisted-older-data',
      dataUpdatedAt: 100,
      error: persistedError,
      errorUpdatedAt: 400,
      fetchFailureCount: 2,
      fetchFailureReason: persistedError,
      status: 'error',
    })

    // Merge persisted into existing
    const merged = mergeQueryState(query.state, persistedState)

    // Newer data should win (existing)
    expect(merged.data).toBe('existing-newer-data')
    expect(merged.dataUpdatedAt).toBe(500)

    // Newer error should win (persisted)
    expect(merged.error?.message).toBe('persisted-error')
    expect(merged.errorUpdatedAt).toBe(400)
    expect(merged.fetchFailureCount).toBe(2)

    // Status should be error (refetch-error) since both data and error present
    expect(merged.status).toBe('error')
  })
})
"}

