describe('mergePersistedState', () => {
  let queryClient: QueryClient
  let queryCache: QueryCache

  beforeEach(() => {
    vi.useFakeTimers()
    queryClient = new QueryClient()
    queryCache = queryClient.getQueryCache()
    queryClient.mount()
  })

  afterEach(() => {
    queryClient.clear()
    vi.useRealTimers()
  })

  it('live newer data + persisted newer error → keep live data, adopt persisted error', async () => {
    const key = queryKey()
    const liveError = new Error('live error')
    const persistedError = new Error('persisted error')

    // First, create data in the live cache
    await queryClient.prefetchQuery({
      queryKey: key,
      queryFn: () => 'live-data',
      persister: () =>
        createPersisterRestoreResult({
          data: 'live-data',
          state: {
            dataUpdateCount: 1,
            dataUpdatedAt: 1000,
            error: null,
            errorUpdateCount: 0,
            errorUpdatedAt: 0,
            fetchFailureCount: 0,
            fetchFailureReason: null,
            isInvalidated: false,
            status: 'success' as const,
            fetchStatus: 'idle' as const,
          },
        }),
    })

    const liveDataUpdatedAt = Date.now() + 1000

    // Now simulate a persisted state that has:
    // - Older data (dataUpdatedAt < live)
    // - Newer error (errorUpdatedAt > live's 0)
    // We use hydrate to apply the merge
    await queryClient.getQueryCache().get(queryClient.getQueryCache().get(
      queryClient.defaultQueryOptions({ queryKey: key }).queryHash,
    )!.queryHash)!
    // Force live data to have a newer timestamp
    queryClient.setQueryData(key, 'live-data', {
      updatedAt: liveDataUpdatedAt,
    })

    const query = queryCache.find({ queryKey: key })!
    expect(query.state.data).toBe('live-data')

    // Now simulate hydration with persisted state that has newer error
    const { hydrate, mergePersistedState } = await import('../hydration')

    const persistedState = {
      data: 'persisted-data',
      dataUpdateCount: 2,
      dataUpdatedAt: 500, // older than live
      error: persistedError,
      errorUpdateCount: 3,
      errorUpdatedAt: liveDataUpdatedAt + 500, // newer than live's 0 error timestamp
      fetchFailureCount: 4,
      fetchFailureReason: persistedError,
      isInvalidated: false,
      status: 'error' as const,
      fetchStatus: 'idle' as const,
    }

    const merged = mergePersistedState(query.state, persistedState)

    // Live data should be kept (newer dataUpdatedAt)
    expect(merged.data).toBe('live-data')
    expect(merged.dataUpdatedAt).toBe(liveDataUpdatedAt)
    // Persisted error should be adopted (newer errorUpdatedAt)
    expect(merged.error).toBe(persistedError)
    expect(merged.errorUpdatedAt).toBe(liveDataUpdatedAt + 500)
    expect(merged.errorUpdateCount).toBe(3)
    // With both data and error, status should be 'error'
    expect(merged.status).toBe('error')
    expect(merged.fetchStatus).toBe('idle')
  })

  it('persisted newer data + live newer error → keep persisted data, adopt live error', async () => {
    const key = queryKey()
    const liveError = new Error('live error')

    // Create live data with newer error timestamp
    await queryClient.prefetchQuery({
      queryKey: key,
      queryFn: () => 'live-data',
      persister: () =>
        createPersisterRestoreResult({
          data: 'live-data',
          state: {
            dataUpdateCount: 1,
            dataUpdatedAt: 100,
            error: null,
            errorUpdateCount: 0,
            errorUpdatedAt: 0,
            fetchFailureCount: 0,
            fetchFailureReason: null,
            isInvalidated: false,
            status: 'success' as const,
            fetchStatus: 'idle' as const,
          },
        }),
    })

    // Now force live into error state with a newer error timestamp
    queryClient.setQueryData(key, 'live-data')
    // Manually set error state via cache
    const query = queryCache.find({ queryKey: key })!
    query.setState({
      error: liveError,
      errorUpdatedAt: 2000,
      errorUpdateCount: 2,
      fetchFailureCount: 2,
      fetchFailureReason: liveError,
      status: 'error',
    })

    const stateBeforeHydrate = query.state

    // Now simulate hydrate with persisted state that has newer data
    const { mergePersistedState } = await import('../hydration')

    const persistedState = {
      data: 'persisted-newer-data',
      dataUpdateCount: 5,
      dataUpdatedAt: 3000, // newer than live's 100
      error: new Error('persisted older error'),
      errorUpdateCount: 1,
      errorUpdatedAt: 500, // older than live's 2000
      fetchFailureCount: 1,
      fetchFailureReason: new Error('persisted older error'),
      isInvalidated: false,
      status: 'error' as const,
      fetchStatus: 'idle' as const,
    }

