    // Persisted data should be kept (newer dataUpdatedAt)
    expect(merged.data).toBe('persisted-newer-data')
    expect(merged.dataUpdatedAt).toBe(3000)
    expect(merged.dataUpdateCount).toBe(5)
    // Live error should be kept (newer errorUpdatedAt)
    expect(merged.error).toBe(liveError)
    expect(merged.errorUpdatedAt).toBe(2000)
    expect(merged.errorUpdateCount).toBe(2)
    expect(merged.fetchFailureCount).toBe(2)
    // With both data and error, status should be 'error'
    expect(merged.status).toBe('error')
    expect(merged.fetchStatus).toBe('idle')
  })

  it('same data and error timestamps → live side wins for data (>= rule), persisted wins for error', async () => {
    const key = queryKey()
    const persistedError = new Error('persisted error')

