            status: 'success' as const,
            fetchStatus: 'idle' as const,
          },
        }),
    })

    const query = queryCache.find({ queryKey: key })!

    const { mergePersistedState } = await import('../hydration')

    // Both sides have dataUpdatedAt=1000 (live >= persisted → live wins)
    // Persisted has errorUpdatedAt=2000 (persisted > live 0 → persisted wins)
    const persistedState = {
      data: 'persisted-data',
      dataUpdateCount: 2,
      dataUpdatedAt: 1000, // same as live
      error: persistedError,
      errorUpdateCount: 3,
      errorUpdatedAt: 2000, // newer than live's 0
      fetchFailureCount: 3,
      fetchFailureReason: persistedError,
      isInvalidated: false,
      status: 'error' as const,
      fetchStatus: 'idle' as const,
    }

    const merged = mergePersistedState(query.state, persistedState)

    // Live data kept via >= rule
    expect(merged.data).toBe('live-data')
    expect(merged.dataUpdatedAt).toBe(1000)
    // Persisted error adopted
    expect(merged.error).toBe(persistedError)
    expect(merged.errorUpdatedAt).toBe(2000)
    expect(merged.errorUpdateCount).toBe(3)
    expect(merged.fetchFailureCount).toBe(3)
    // Both data and error → refetch error
    expect(merged.status).toBe('error')
  })

  it('does not replace entire state — counts from winning sides per dimension', async () => {
    const key = queryKey()

    // Create live query with specific counts
    await queryClient.prefetchQuery({
      queryKey: key,
