        createPersisterRestoreResult({
          data: 'live-data',
          state: {
            dataUpdateCount: 5,
            dataUpdatedAt: 1000,
            error: null,
            errorUpdateCount: 99,
            errorUpdatedAt: 1000,
            fetchFailureCount: 99,
            fetchFailureReason: null,
            isInvalidated: false,
            status: 'success' as const,
            fetchStatus: 'idle' as const,
          },
        }),
    })

    const query = queryCache.find({ queryKey: key })!
    // live has dataUpdateCount=5, errorUpdateCount=0

    const { mergePersistedState } = await import('../hydration')

    // Persisted: newer data (2000>1000), older error (500<1000)
    const persistedState = {
      data: 'persisted-data',
      dataUpdateCount: 10,
      dataUpdatedAt: 2000, // newer
      error: new Error('persisted err'),
      errorUpdateCount: 7,
      errorUpdatedAt: 500, // older
      fetchFailureCount: 7,
      fetchFailureReason: new Error('persisted err'),
      isInvalidated: false,
      status: 'error' as const,
      fetchStatus: 'idle' as const,
    }

    const merged = mergePersistedState(query.state, persistedState)

    // data from persisted (newer), error from live (newer)
    expect(merged.data).toBe('persisted-data')
