    expect(merged.error).toBeNull() // live has null error, and null error is not "newer" than persisted error
    // Wait - live.error is null with errorUpdatedAt=1000, persisted.error is Error with errorUpdatedAt=500
    // live.errorUpdatedAt (1000) > persisted.errorUpdatedAt (500), so live error wins
