    @classmethod
    def combine(
        cls,
        first: 'Validated[_NewValueType, _NewErrorType]',
        second: 'Validated[_NewValueType, _NewErrorType]',
        function: Callable[[_NewValueType, _NewValueType], _NewValueType],
    ) -> 'Validated[_NewValueType, _NewErrorType]':
        """
        Combines two ``Validated`` values using applicative style.

        If both are ``Valid``, applies the binary function to their values.
        If either is ``Invalid``, errors are accumulated.

        .. code:: python

          >>> from returns.validated import Validated, Valid, Invalid

          >>> assert Validated.combine(Valid(1), Valid(2), lambda a, b: a + b)
          ...     == Valid(3)
          >>> assert Validated.combine(
          ...     Invalid((1,)), Valid(2), lambda a, b: a + b,
          ... ) == Invalid((1,))
          >>> assert Validated.combine(
          ...     Invalid((1,)), Invalid((2,)), lambda a, b: a + b,
          ... ) == Invalid((1, 2))

        """
        return second.apply(first.apply(cls.from_value(
            lambda x: lambda y: function(x, y),
        )))

    @classmethod
    def combine_n(
        cls,
        containers: tuple['Validated[_NewValueType, _NewErrorType]', ...],
        function: Callable[..., _NewValueType],
    ) -> 'Validated[_NewValueType, _NewErrorType]':
        """
        Combines N ``Validated`` values using applicative style.

        Accumulates all errors if any are invalid.

        .. code:: python

          >>> from returns.validated import Validated, Valid, Invalid

          >>> assert Validated.combine_n(
          ...     (Valid(1), Valid(2), Valid(3)),
          ...     lambda a, b, c: a + b + c,
          ... ) == Valid(6)
          >>> assert Validated.combine_n(
          ...     (Invalid((1,)), Valid(2), Invalid((3,))),
          ...     lambda a, b, c: a + b + c,
          ... ) == Invalid((1, 3))

        """
        lifted = cls.from_value(_curry(function, len(containers)))  # type: ignore
        for container in containers:
            lifted = container.apply(lifted)
        return lifted  # type: ignore


def _curry(function: Callable[..., _NewValueType], arity: int) -> Callable[..., Any]:
    """Curries a function to the given arity."""
    def curried(*args: Any) -> Any:
        if len(args) >= arity:
            return function(*args)
        return lambda *more_args: curried(*args, *more_args)
    return curried


