/**
  Given an iterable of {@linkcode Task}s, collect them into a single `Task` of
  an array. If any task is rejected, stop consuming tasks and return that first
  rejection.

  ## Examples

  ```ts
  import { sequence } from 'true-myth/task';

  let tasks = [Task.resolve(1), Task.resolve(2)];
  let result = await sequence(tasks);
  // => Ok([1, 2])
  ```

  @param tasks An iterable of tasks to collect.
  @template T The resolved type.
  @template E The rejected type.
 */
export function sequence<T, E>(tasks: Iterable<Task<T, E>>): Task<T[], E> {
  return Task.resolve().andThen(async () => {
    const items: T[] = [];

    for (const task of tasks) {
      const result = await task;
      if (result.isErr) {
        return result as unknown as Result<T[], E>;
      }
      items.push(result.value);
    }

    return Result.ok(items);
  });
}

/**
  Map a function over an iterable and {@linkcode sequence} the results. Stops
  advancing the iterator after the first rejection.

  ## Examples

  Non-curried form:

  ```ts
  import { traverse } from 'true-myth/task';

  const parseNum = (s: string) =>
    Number.isNaN(Number(s))
      ? Task.reject(`bad: ${s}`)
      : Task.resolve(Number(s));

  let result = await traverse(['1', '2', '3'], parseNum);
  // => Ok([1, 2, 3])
  ```

  Curried form:

  ```ts
  import { traverse } from 'true-myth/task';

  const parseNum = (s: string) =>
    Number.isNaN(Number(s))
      ? Task.reject(`bad: ${s}`)
      : Task.resolve(Number(s));

  const tryParse = traverse(parseNum);
  let result = await tryParse(['1', '2', '3']);
  // => Ok([1, 2, 3])
  ```

  @template T The input item type.
  @template U The output resolved type.
  @template E The rejected type.
 */
export function traverse<T, U, E>(
  fn: (item: T) => Task<U, E>
): (items: Iterable<T>) => Task<U[], E>;
export function traverse<T, U, E>(
  items: Iterable<T>,
  fn: (item: T) => Task<U, E>
): Task<U[], E>;
export function traverse<T, U, E>(
  itemsOrFn: Iterable<T> | ((item: T) => Task<U, E>),
  fn?: (item: T) => Task<U, E>
): Task<U[], E> | ((items: Iterable<T>) => Task<U[], E>) {
  if (typeof itemsOrFn === 'function') {
    const mappingFn = itemsOrFn;
    return (items: Iterable<T>) => {
      return Task.resolve().andThen(async () => {
        const results: U[] = [];
        for (const item of items) {
          const result = await mappingFn(item);
          if (result.isErr) {
            return result as unknown as Result<U[], E>;
          }
          results.push(result.value);
        }
        return Result.ok(results);
      });
    };
  } else {
    const mappingFn = fn!;
    return Task.resolve().andThen(async () => {
      const results: U[] = [];
      for (const item of itemsOrFn) {
        const result = await mappingFn(item);
        if (result.isErr) {
          return result as unknown as Result<U[], E>;
        }
        results.push(result.value);
      }
      return Result.ok(results);
    });
  }
}

/**
