import { Pattern } from './types/Pattern';
import { MatchEach } from './types/MatchEach';
import * as symbols from './internals/symbols';
import { matchPattern } from './internals/helpers';
import { NonExhaustiveError } from './errors';

type Clause<input, output> = {
  patterns: unknown[];
  predicate: ((value: input) => unknown) | undefined;
  handler: (selection: unknown, value: input) => output;
};

type TapCallback<output> = (value: output) => void;

/**
 * `matchEach` creates a **pattern matching expression** that evaluates ALL
 * registered patterns against the input and collects every matching
 * handler's result into an array, returned in the order clauses were declared.
 *
 * Unlike `match`, which short-circuits on the first matching pattern,
 * `matchEach` evaluates every clause and returns an array of all results.
 *
 * @example
 *  declare let input: "A" | "B" | "C";
 *
 *  return matchEach(input)
 *    .with("A", () => "It's an A!")
 *    .with("B", () => "It's a B!")
 *    .with("C", () => "It's a C!")
 *    .exhaustive();
 *  // returns ["It's an A!", "It's a B!", "It's a C!"]
 */
export function matchEach<const input, output = symbols.unset>(
  value: input
): MatchEach<input, output>;
export function matchEach<const input, output = symbols.unset>(): (
  value: input
) => MatchEach<input, output>;
export function matchEach<const input, output = symbols.unset>(
  value?: input
): MatchEach<input, output> | ((value: input) => MatchEach<input, output>) {
  if (arguments.length === 0) {
    // Return a function that takes a value
    return (v: input) => new MatchEachExpression(v, []) as any;
  }
  return new MatchEachExpression(value!, []) as any;
}

/**
 * This class represents a matchEach expression. It follows the
 * builder pattern, we chain methods to add features to the expression
 * until we call `.exhaustive`, `.otherwise` or `.run` method to execute it.
 *
 * Unlike MatchExpression, this class does NOT short-circuit on the first
 * match. Instead it collects ALL matching results into an array.
 */
class MatchEachExpression<input, output> {
  private clauses: Clause<input, output>[] = [];
  private tapCallbacks: TapCallback<output>[] = [];

  constructor(
    private input: input,
    _initialClauses?: Clause<input, output>[]
  ) {
    if (_initialClauses) {
      this.clauses = [..._initialClauses];
    }
  }

  with(...args: any[]): MatchEachExpression<input, output> {
    const handler: (selection: unknown, value: input) => output =
      args[args.length - 1];

    const patterns: unknown[] = [args[0]];
    let predicate: ((value: input) => unknown) | undefined = undefined;

    if (args.length === 3 && typeof args[1] === 'function') {
      // case with guard as second argument
      predicate = args[1];
    } else if (args.length > 2) {
      // case with several patterns
      patterns.push(...args.slice(1, args.length - 1));
    }

    this.clauses.push({
      patterns,
      predicate,
      handler,
    });

    return this;
  }

  when(
    predicate: (value: input) => unknown,
    handler: (selection: input, value: input) => output
  ): MatchEachExpression<input, output> {
    this.clauses.push({
      patterns: [predicate],
      predicate: undefined,
      handler: handler as any,
    });
    return this;
  }

  tap(callback: TapCallback<output>): MatchEachExpression<input, output> {
    this.tapCallbacks.push(callback);
    return this;
  }

  otherwise(handler: (value: input) => output): output[] {
    const results = this.evaluate();

    if (results.length > 0) {
      return results;
    }

    const fallbackResult = handler(this.input);
    this.runTapCallbacks([fallbackResult]);
    return [fallbackResult];
  }

  exhaustive(
    unexpectedValueHandler?: (value: unknown) => output
  ): output[] {
    const results = this.evaluate();

    if (results.length > 0) {
      return results;
    }

    if (unexpectedValueHandler) {
      const result = unexpectedValueHandler(this.input);
      this.runTapCallbacks([result]);
      return [result];
    }

    throw new NonExhaustiveError(this.input);
  }

  run(): output[] {
    return this.exhaustive();
  }

  returnType() {
    return this;
  }

  narrow() {
    return this;
  }

  toFunction(): (value: input) => output[] {
    const clauses = [...this.clauses];
    const tapCallbacks = [...this.tapCallbacks];

    return (value: input): output[] => {
      return evaluateClauses(clauses, tapCallbacks, value);
    };
  }

  toExhaustiveFunction(): (value: input) => output[] {
    const clauses = [...this.clauses];
    const tapCallbacks = [...this.tapCallbacks];

    return (value: input): output[] => {
      const results = evaluateClauses(clauses, tapCallbacks, value);

      if (results.length === 0) {
        throw new NonExhaustiveError(value);
      }

      return results;
    };
  }

  toPartialFunction(): (value: input) => output[] | undefined {
    const clauses = [...this.clauses];
    const tapCallbacks = [...this.tapCallbacks];

    return (value: input): output[] | undefined => {
      const results = evaluateClauses(clauses, tapCallbacks, value);

      if (results.length === 0) {
        return undefined;
      }

      return results;
    };
  }

  private evaluate(): output[] {
    const results: output[] = [];

    for (const clause of this.clauses) {
      const result = this.evaluateClause(clause);
      if (result !== undefined) {
        results.push(result);
        this.runTapCallbacks(results);
      }
    }

    return results;
  }

  private evaluateClause(clause: Clause<input, output>): output | undefined {
    let hasSelections = false;
    let selected: Record<string, unknown> = {};
    const select = (key: string, value: unknown) => {
      hasSelections = true;
      selected[key] = value;
    };

    const matched = clause.patterns.some((pattern) =>
      matchPattern(pattern, this.input, select)
    );

    if (!matched) return undefined;

    if (clause.predicate && !Boolean(clause.predicate(this.input))) {
      return undefined;
    }

    const selections = hasSelections
      ? symbols.anonymousSelectKey in selected
        ? selected[symbols.anonymousSelectKey]
        : selected
      : this.input;

    return clause.handler(selections, this.input);
  }

  private runTapCallbacks(currentResults: output[]): void {
    for (const callback of this.tapCallbacks) {
      for (const result of currentResults) {
        callback(result);
      }
    }
  }
}

function evaluateClauses<input, output>(
  clauses: Clause<input, output>[],
  tapCallbacks: TapCallback<output>[],
  value: input
): output[] {
  const results: output[] = [];

  for (const clause of clauses) {
    let hasSelections = false;
    let selected: Record<string, unknown> = {};
    const select = (key: string, v: unknown) => {
      hasSelections = true;
      selected[key] = v;
    };

    const matched = clause.patterns.some((pattern) =>
      matchPattern(pattern, value, select)
    );

    if (!matched) continue;

    if (clause.predicate && !Boolean(clause.predicate(value))) {
      continue;
    }

    const selections = hasSelections
      ? symbols.anonymousSelectKey in selected
        ? selected[symbols.anonymousSelectKey]
        : selected
      : value;

    results.push(clause.handler(selections, value));
  }

  for (const callback of tapCallbacks) {
    for (const result of results) {
      callback(result);
    }
  }

  return results;
}

