import { MatchEach } from './types/MatchEach';
import * as symbols from './internals/symbols';
import { matchPattern } from './internals/helpers';
import { NonExhaustiveError } from './errors';

type Clause<input, output> = {
  patterns: unknown[];
  predicate: ((value: input) => unknown) | undefined;
  handler: (selection: unknown, value: input) => output;
};

type TapCallback<output> = (value: output) => void;

type Step<input, output> =
  | { kind: 'clause'; clause: Clause<input, output> }
  | { kind: 'tap'; callback: TapCallback<output> };

/**
 * `matchEach` creates a **pattern matching expression** that evaluates ALL
 * registered patterns against the input and collects every matching
 * handler's result into an array, returned in the order clauses were declared.
 *
 * Unlike `match`, which short-circuits on the first matching pattern,
 * `matchEach` evaluates every clause and returns an array of all results.
 *
 * @example
 *  declare let input: "A" | "B" | "C";
 *
 *  return matchEach(input)
 *    .with("A", () => "It's an A!")
 *    .with("B", () => "It's a B!")
 *    .with("C", () => "It's a C!")
 *    .exhaustive();
 *  // returns ["It's an A!", "It's a B!", "It's a C!"]
 */
export function matchEach<const input, output = symbols.unset>(
  value: input
): MatchEach<input, output>;
/**
 * `matchEach` can also be called without a value argument using explicit type
 * parameters to build a reusable compiled matcher.
 *
 * @example
 *  const f = matchEach<string | number>()
 *    .with(P.string, (x) => `s:${x}`)
 *    .toFunction();
 */
export function matchEach<const input, output = symbols.unset>(): MatchEach<
  input,
  output
>;
export function matchEach<const input, output = symbols.unset>(
  value?: input
): MatchEach<input, output> {
  return new MatchEachExpression<input, output>(value as input) as any;
}

/**
 * This class represents a matchEach expression. It follows the
 * builder pattern, we chain methods to add features to the expression
 * until we call `.exhaustive`, `.otherwise` or `.run` method to execute it.
 *
 * Unlike MatchExpression, this class does NOT short-circuit on the first
 * match. Instead it collects ALL matching results into an array.
 */
class MatchEachExpression<input, output> {
  private steps: Step<input, output>[] = [];
  private hasInput: boolean;

  constructor(private input: input) {
    this.hasInput = arguments.length > 0;
  }

  private assertHasInput(method: string): void {
    if (!this.hasInput) {
      throw new Error(
        `\`matchEach().${method}()\` cannot be called on a matchEach expression ` +
          `without an input value. Either pass a value to \`matchEach(value)\` ` +
          `or use one of the compiled function methods: \`.toFunction()\`, ` +
          `\`.toExhaustiveFunction()\`, or \`.toPartialFunction()\`.`
      );
    }
  }

  with(...args: any[]): MatchEachExpression<input, output> {
    const handler: (selection: unknown, value: input) => output =
      args[args.length - 1];

    const patterns: unknown[] = [args[0]];
    let predicate: ((value: input) => unknown) | undefined = undefined;

    if (args.length === 3 && typeof args[1] === 'function') {
      // case with guard as second argument
      predicate = args[1];
    } else if (args.length > 2) {
      // case with several patterns
      patterns.push(...args.slice(1, args.length - 1));
    }

    this.steps.push({
      kind: 'clause',
      clause: { patterns, predicate, handler },
    });

    return this;
  }

  when(
    predicate: (value: input) => unknown,
    handler: (selection: input, value: input) => output
  ): MatchEachExpression<input, output> {
    // For when(), we store a clause with a sentinel pattern that is never
    // matched via matchPattern; instead we evaluate the predicate directly
    // during evaluation.
    this.steps.push({
      kind: 'clause',
      clause: {
        patterns: [],
        predicate,
        handler: handler as any,
      },
    });
    return this;
  }

  tap(callback: TapCallback<output>): MatchEachExpression<input, output> {
    this.steps.push({
      kind: 'tap',
      callback,
    });
    return this;
  }

  otherwise(handler: (value: input) => output): output[] {
    this.assertHasInput('otherwise');
    const results = this.evaluateSteps();

    if (results.length > 0) {
      return results;
    }

    // No matches: return the fallback in a single-element array
    return [handler(this.input)];
  }

  exhaustive(unexpectedValueHandler?: (value: unknown) => output): output[] {
    this.assertHasInput('exhaustive');
    const results = this.evaluateSteps();

    if (results.length > 0) {
      return results;
    }

    if (unexpectedValueHandler) {
      return [unexpectedValueHandler(this.input)];
    }

    throw new NonExhaustiveError(this.input);
  }

  run(): output[] {
    return this.exhaustive();
  }

  returnType() {
    return this;
  }

  narrow() {
    return this;
  }

  toFunction(): (value: input) => output[] {
    const steps = this.steps;

    return (value: input): output[] => {
      return evaluateSteps(steps, value);
    };
  }

  toExhaustiveFunction(): (value: input) => output[] {
    const steps = this.steps;

    return (value: input): output[] => {
      const results = evaluateSteps(steps, value);

      if (results.length === 0) {
        throw new NonExhaustiveError(value);
      }

      return results;
    };
  }

  toPartialFunction(): (value: input) => output[] | undefined {
    const steps = this.steps;

    return (value: input): output[] | undefined => {
      const results = evaluateSteps(steps, value);

      if (results.length === 0) {
        return undefined;
      }

      return results;
    };
  }

  private evaluateSteps(): output[] {
    return evaluateSteps(this.steps, this.input);
  }
}

function evaluateStepClause<input, output>(
  clause: Clause<input, output>,
  value: input
): output | undefined {
  let hasSelections = false;
  let selected: Record<string, unknown> = {};
  const select = (key: string, v: unknown) => {
    hasSelections = true;
    selected[key] = v;
  };

  // For when() clauses, patterns array is empty and we use the predicate directly
  if (clause.patterns.length === 0) {
    // This is a when() clause - evaluate predicate directly
    if (!clause.predicate) return undefined;
    if (!Boolean(clause.predicate(value))) return undefined;

    const selections = value;
    return clause.handler(selections, value);
  }

  // For with() clauses
  const matched = clause.patterns.some((pattern) =>
    matchPattern(pattern, value, select)
  );

  if (!matched) return undefined;

  if (clause.predicate && !Boolean(clause.predicate(value))) {
    return undefined;
  }

  const selections = hasSelections
    ? symbols.anonymousSelectKey in selected
      ? selected[symbols.anonymousSelectKey]
      : selected
    : value;

  return clause.handler(selections, value);
}

function evaluateSteps<input, output>(
  steps: Step<input, output>[],
  value: input
): output[] {
  const results: output[] = [];

  for (const step of steps) {
    if (step.kind === 'clause') {
      const result = evaluateStepClause(step.clause, value);
      if (result !== undefined) {
        results.push(result);
      }
    } else if (step.kind === 'tap') {
      // Fire the tap callback once per result accumulated so far
      for (const result of results) {
        step.callback(result);
      }
    }
  }

  return results;
}
