describe('duration-smoothing', () => {
  const observations = [
    { duration: 100, recordedAt: 1 },
    { duration: 200, recordedAt: 3 },
    { duration: 150, recordedAt: 2 },
    { duration: 300, recordedAt: 5 },
    { duration: 50, recordedAt: 4 },
  ]

  test('latest returns highest recordedAt', () => {
    expect(smoothLatest(observations)).toBe(300) // recordedAt: 5
  })

  test('average returns rounded mean', () => {
    // (100 + 200 + 150 + 300 + 50) / 5 = 800/5 = 160
    expect(smoothAverage(observations)).toBe(160)
  })

  test('p95 returns correct percentile', () => {
    // Sorted durations: [50, 100, 150, 200, 300]
    // ceil(0.95 * 5) - 1 = ceil(4.75) - 1 = 5 - 1 = 4 => index 4 = 300
    expect(smoothP95(observations)).toBe(300)
  })

  test('p95 with 3 observations', () => {
    const obs = [
      { duration: 10, recordedAt: 1 },
      { duration: 20, recordedAt: 2 },
      { duration: 30, recordedAt: 3 },
    ]
    // ceil(0.95 * 3) - 1 = ceil(2.85) - 1 = 3 - 1 = 2 => index 2 = 30
    expect(smoothP95(obs)).toBe(30)
  })

  test('median with odd count', () => {
    // Sorted: [50, 100, 150, 200, 300] => middle = 150
    expect(smoothMedian(observations)).toBe(150)
  })

  test('median with even count', () => {
    const obs = [
      { duration: 10, recordedAt: 1 },
      { duration: 20, recordedAt: 2 },
      { duration: 30, recordedAt: 3 },
      { duration: 40, recordedAt: 4 },
    ]
    // Sorted: [10, 20, 30, 40] => (20 + 30) / 2 = 25
    expect(smoothMedian(obs)).toBe(25)
  })

  test('getSmoothingFn returns correct functions', () => {
    expect(getSmoothingFn('latest')).toBe(smoothLatest)
    expect(getSmoothingFn('average')).toBe(smoothAverage)
    expect(getSmoothingFn('p95')).toBe(smoothP95)
    expect(getSmoothingFn('median')).toBe(smoothMedian)
  })
})

