describe('shard-affinity', () => {
  describe('matchAffinityRule', () => {
    const rules = [
      { pattern: 'test/slow/**', shardIndex: 0 },
      { pattern: 'test/flaky/**', shardIndex: 1 },
    ]

    test('matches by glob pattern', () => {
      expect(matchAffinityRule('test/slow/foo.test.ts', rules, 4)).toBe(0)
      expect(matchAffinityRule('test/flaky/bar.test.ts', rules, 4)).toBe(1)
    })

    test('first match wins', () => {
      const dupRules = [
        { pattern: 'test/**', shardIndex: 0 },
        { pattern: 'test/slow/**', shardIndex: 1 },
      ]
      expect(matchAffinityRule('test/slow/foo.test.ts', dupRules, 4)).toBe(0)
    })

    test('clamps shardIndex to shardCount - 1', () => {
      expect(matchAffinityRule('test/slow/foo.test.ts', rules, 1)).toBe(0) // clamped to 0
    })

    test('returns null for no match', () => {
      expect(matchAffinityRule('other/file.test.ts', rules, 4)).toBeNull()
    })

    test('returns null for empty rules', () => {
      expect(matchAffinityRule('test/slow/foo.test.ts', [], 4)).toBeNull()
    })
  })

  describe('resolveAffinityAssignments', () => {
    test('returns map of matched files', () => {
      const rules = [
        { pattern: 'test/slow/**', shardIndex: 0 },
        { pattern: 'test/fast/**', shardIndex: 1 },
      ]
      const files = [
        'test/slow/a.test.ts',
        'test/fast/b.test.ts',
        'other/c.test.ts',
      ]
      const result = resolveAffinityAssignments(files, rules, 3)
      expect(result.get('test/slow/a.test.ts')).toBe(0)
      expect(result.get('test/fast/b.test.ts')).toBe(1)
      expect(result.has('other/c.test.ts')).toBe(false)
      expect(result.size).toBe(2)
    })
  })
})

