describe('shard-analytics', () => {
  function buildSpec(moduleId: string): TestSpecification {
    const workspace = {
      name: 'test',
      config: { root: '/root', sequence: { groupOrder: 0 } },
    } as any as TestProject
    return new TestSpecification(workspace, moduleId, 'forks')
  }

  const files = [
    { spec: buildSpec('/root/test/a.test.ts'), duration: 100, relativePath: 'test/a.test.ts' },
    { spec: buildSpec('/root/test/b.test.ts'), duration: 200, relativePath: 'test/b.test.ts' },
    { spec: buildSpec('/root/test/c.test.ts'), duration: 300, relativePath: 'test/c.test.ts' },
    { spec: buildSpec('/root/test/d.test.ts'), duration: 400, relativePath: 'test/d.test.ts' },
  ]

  describe('shardHash', () => {
    test('distributes files by hash', () => {
      const specs = files.map(f => f.spec)
      const result = shardHash(specs, 1, 2)
      // Hash-based, just verify we get some files back
      expect(result.length).toBeGreaterThan(0)
      expect(result.length).toBeLessThanOrEqual(specs.length)
    })

    test('all shards cover all files', () => {
      const specs = files.map(f => f.spec)
      const allResults = []
      for (let i = 1; i <= 2; i++) {
        allResults.push(...shardHash(specs, i, 2))
      }
      expect(new Set(allResults)).toEqual(new Set(specs))
    })
  })

  describe('shardEqualSplit', () => {
    test('distributes files by index', () => {
      const specs = files.map(f => f.spec)
      const shard1 = shardEqualSplit(specs, 1, 2)
      const shard2 = shardEqualSplit(specs, 2, 2)
      expect(shard1.length + shard2.length).toBe(specs.length)
    })
  })

  describe('shardTime', () => {
    test('assigns longest file to first shard', () => {
      const result = shardTime(files, 1, 2)
      // The longest file (400) should go to shard 1 first
      expect(result).toContain(files[3].spec) // d.test.ts (400ms)
    })
  })

  describe('shardRoundRobin', () => {
    test('distributes files with bouncing pointer', () => {
      const result = shardRoundRobin(files, 1, 2)
      expect(result).toBeDefined()
    })
  })

  describe('shardAffinity', () => {
    test('assigns affinity-matched files to specified shards', () => {
      const rules = [{ pattern: 'test/a.test.ts', shardIndex: 1 }]
      const result = shardAffinity(files, 2, 2, rules)
      expect(result).toContain(files[0].spec) // a.test.ts matched to shard 1 (0-based: 1)
    })

    test('falls back to time when no rule matches', () => {
      const result = shardAffinity(files, 1, 2, [
        { pattern: 'nomatch/**', shardIndex: 0 },
      ])
      expect(result).toBeDefined()
    })

    test('handles empty rules', () => {
      const result = shardAffinity(files, 1, 2, [])
      expect(result).toBeDefined()
    })
  })

  describe('isolateSlowFiles', () => {
    test('splits files by threshold', () => {
      const result = isolateSlowFiles(files, 1, 3, 250)
      expect(result.slowSpecs).toHaveLength(2) // 300 and 400 > 250
      expect(result.remainingSpecs).toHaveLength(2) // 100 and 200 <= 250
    })

    test('returns all remaining when threshold is 0', () => {
      const result = isolateSlowFiles(files, 1, 3, 0)
      expect(result.slowSpecs).toHaveLength(0)
      expect(result.remainingSpecs).toHaveLength(4)
    })
  })

  describe('mergeSlowFiles', () => {
    test('distributes one slow file per shard', () => {
      const slowSpecs = [buildSpec('/root/slow1.ts'), buildSpec('/root/slow2.ts')]
      const shardSpecs = [buildSpec('/root/fast1.ts')]
      const result = mergeSlowFiles(1, 2, slowSpecs, shardSpecs)
      expect(result).toHaveLength(2) // shard 1 gets fast1 + slow1
    })

    test('last shard gets all extras when slow >= count', () => {
      const slowSpecs = [
        buildSpec('/root/slow1.ts'),
        buildSpec('/root/slow2.ts'),
        buildSpec('/root/slow3.ts'),
      ]
      const shardSpecs = [buildSpec('/root/fast1.ts')]
      // Shard 2 (index=1, 0-based) is the last shard (count=2)
      const result = mergeSlowFiles(2, 2, slowSpecs, shardSpecs)
      // Last shard gets slowSpecs[1] + slowSpecs[2] (extras)
      expect(result).toHaveLength(3)
    })
  })

  describe('checkRebalanceThreshold', () => {
    test('returns undefined when threshold is 0', () => {
      expect(checkRebalanceThreshold([100, 200], 0)).toBeUndefined()
    })

    test('returns undefined when loads are balanced', () => {
      expect(checkRebalanceThreshold([100, 100], 1)).toBeUndefined()
    })

    test('returns ratio when imbalance exceeds threshold', () => {
      const ratio = checkRebalanceThreshold([100, 10], 0.5)
      expect(ratio).toBeDefined()
      expect(ratio!).toBeCloseTo(0.1)
    })
  })

  describe('sortByDuration', () => {
    test('sorts by duration descending', () => {
      const input = [
        { spec: buildSpec('/root/a.ts'), duration: 100, relativePath: 'a.ts' },
        { spec: buildSpec('/root/b.ts'), duration: 300, relativePath: 'b.ts' },
      ]
      const result = sortByDuration(input)
      expect(result[0].duration).toBe(300)
      expect(result[1].duration).toBe(100)
    })

    test('absent-from-history (duration 0) goes last', () => {
      const input = [
        { spec: buildSpec('/root/a.ts'), duration: 100, relativePath: 'a.ts' },
        { spec: buildSpec('/root/b.ts'), duration: 0, relativePath: 'b.ts' },
        { spec: buildSpec('/root/c.ts'), duration: 200, relativePath: 'c.ts' },
      ]
      const result = sortByDuration(input)
      expect(result[0].duration).toBe(200)
      expect(result[1].duration).toBe(100)
      expect(result[2].duration).toBe(0)
    })
  })

  describe('computeShardLoads functions', () => {
    test('computeShardLoadsHash returns per-shard totals', () => {
      const loads = computeShardLoadsHash(files, 2)
      expect(loads).toHaveLength(2)
      expect(loads.reduce((a, b) => a + b, 0)).toBe(1000) // sum of all durations
    })

