      const loads = computeShardLoadsRoundRobin(files, 2)
      expect(loads).toHaveLength(2)
      expect(loads.reduce((a, b) => a + b, 0)).toBe(1000)
    })

    test('computeShardLoadsAffinity returns per-shard totals', () => {
      const loads = computeShardLoadsAffinity(files, 2, [
        { pattern: 'test/a.test.ts', shardIndex: 0 },
      ])
      expect(loads).toHaveLength(2)
