function makeSpec(moduleId: string, projectName = 'test') {
  return {
    moduleId,
    project: {
      name: projectName,
      config: {
        root: '/root',
        sequence: { groupOrder: 0 },
        isolate: true,
      },
    },
  } as any
}

function makeCtx(config?: any, history?: any) {
  return {
    config: {
      root: '/root',
      shard: config?.shard || { index: 1, count: 3 },
      sequence: {
        groupOrder: 0,
        shardStrategy: config?.shardStrategy || 'time',
        balanceShardsByTime: false,
        recordFileDurations: false,
        durationBasedSorting: false,
        durationHistoryTTL: 0,
        durationHistoryPath: 'history.json',
        durationHistoryMaxRuns: 1,
        durationSmoothing: config?.durationSmoothing || 'latest',
        shardAffinityRules: config?.shardAffinityRules || [],
        rebalanceThreshold: config?.rebalanceThreshold || 0,
        isolateSlowThreshold: config?.isolateSlowThreshold || 0,
        durationFallbackStrategy: config?.durationFallbackStrategy || 'hash',
      },
      ...config,
    },
    cache: {
      getFileTestResults: vi.fn(),
      getFileStats: vi.fn(),
    },
    logger: {
      warn: vi.fn(),
    },
  } as any
}

