// minimalWasm is a minimal WebAssembly module that exports 1 page (64KB) of
// linear memory as "memory". It has no imports or function exports.
var minimalWasm = func() []byte {
	magic := []byte{0x00, 0x61, 0x73, 0x6D} // \0asm
	version := []byte{0x01, 0x00, 0x00, 0x00}

	// Memory section (id=5)
	// payload: count=1, flags=0x01 (has max), initial=1, max=1
	memPayload := []byte{0x01, 0x01, 0x01, 0x01}
	memSection := append([]byte{0x05, byte(len(memPayload))}, memPayload...)

	// Export section (id=7)
	// payload: count=1, name="memory" (len=6), kind=0x02 (memory), index=0
	exportPayload := []byte{0x01, 0x06, 'm', 'e', 'm', 'o', 'r', 'y', 0x02, 0x00}
	exportSection := append([]byte{0x07, byte(len(exportPayload))}, exportPayload...)

	var out []byte
	out = append(out, magic...)
	out = append(out, version...)
	out = append(out, memSection...)
	out = append(out, exportSection...)
	return out
}()

// newRuntimeModule creates a new wazero runtime, instantiates the minimal
// module with the given name, and returns the runtime, context, and module.
func newRuntimeModule(t *testing.T, name string) (context.Context, wazero.Runtime, api.Module) {
	t.Helper()
	ctx := context.Background()
	rt := wazero.NewRuntime(ctx)
	mod, err := rt.InstantiateWithConfig(ctx, minimalWasm,
		wazero.NewModuleConfig().WithName(name))
	if err != nil {
		rt.Close(ctx)
		t.Fatal(err)
	}
	return ctx, rt, mod
}

func writeMemory(t *testing.T, mod api.Module, data []byte) {
	t.Helper()
	mem := mod.Memory()
	if mem == nil {
		t.Fatal("module has no memory")
	}
	if uint32(len(data)) > mem.Size() {
		t.Fatal("data exceeds memory size")
	}
	if !mem.Write(0, data) {
		t.Fatal("failed to write memory")
	}
}

// rawModule holds a runtime and module for test cleanup.
type rawModule struct {
	ctx context.Context
	rt  wazero.Runtime
	mod api.Module
}

func newRawModule(t *testing.T, name string) rawModule {
	t.Helper()
	ctx := context.Background()
	rt := wazero.NewRuntime(ctx)
	mod, err := rt.InstantiateWithConfig(ctx, minimalWasm,
		wazero.NewModuleConfig().WithName(name))
	if err != nil {
		rt.Close(ctx)
		t.Fatal(err)
	}
	return rawModule{ctx: ctx, rt: rt, mod: mod}
}

func TestMinimalWasmIsValid(t *testing.T) {
	ctx := context.Background()
	rt := wazero.NewRuntime(ctx)
	defer rt.Close(ctx)
	_, err := rt.Instantiate(ctx, minimalWasm)
	if err != nil {
		t.Fatalf("minimal wasm is invalid: %v", err)
	}
}

