func TestVersion_Monotonic(t *testing.T) {
	ctx, rt, mod := newRuntimeModule(t, "m")
	defer rt.Close(ctx)

	c := snapshot.NewCoordinator()

	s1, err := c.CaptureSnapshot(mod)
	if err != nil {
		t.Fatal(err)
	}
	if s1.Version() != 1 {
		t.Fatalf("expected version 1, got %d", s1.Version())
	}

	s2, err := c.CaptureSnapshot(mod)
	if err != nil {
		t.Fatal(err)
	}
	if s2.Version() != 2 {
		t.Fatalf("expected version 2, got %d", s2.Version())
	}

	// Incremental also increments.
	s3, err := c.CaptureIncremental(s2, mod)
	if err != nil {
		t.Fatal(err)
	}
	if s3.Version() != 3 {
		t.Fatalf("expected version 3, got %d", s3.Version())
