func TestData_Immutability(t *testing.T) {
	ctx, rt, mod := newRuntimeModule(t, "m")
	defer rt.Close(ctx)

	writeMemory(t, mod, []byte{1, 2, 3, 4, 5})
	c := snapshot.NewCoordinator()
	snap, err := c.CaptureSnapshot(mod)
	if err != nil {
		t.Fatal(err)
	}

	// Mutate the returned copy.
	original := snap.Data()
	original[0][0] = 0xFF

	// Get Data again; should be unchanged.
	second := snap.Data()
	if second[0][0] != 1 {
		t.Fatalf("data was mutated: got %d, want 1", second[0][0])
	}
}

func TestTags_Immutability(t *testing.T) {
	ctx, rt, mod := newRuntimeModule(t, "m")
	defer rt.Close(ctx)

	c := snapshot.NewCoordinator()
	snap, err := c.CaptureSnapshot(mod)
	if err != nil {
		t.Fatal(err)
	}

	snap.SetTag("key1", "val1")

	// Get and mutate the copy.
	tags := snap.Tags()
	tags["key1"] = "mutated"

	// Get again; should be unchanged.
	tags2 := snap.Tags()
	if tags2["key1"] != "val1" {
		t.Fatalf("tags were mutated: got %q, want %q", tags2["key1"], "val1")
	}
}

// ---------------------------------------------------------------------------
// CompressedData verification
// ---------------------------------------------------------------------------

func decompressGzip(t *testing.T, compressed []byte) []byte {
	t.Helper()
	r, err := gzip.NewReader(bytes.NewReader(compressed))
	if err != nil {
		t.Fatal(err)
	}
	defer r.Close()
	data, err := io.ReadAll(r)
	if err != nil {
		t.Fatal(err)
	}
	return data
}

func TestCompressedData_FullSnapshot(t *testing.T) {
	ctx, rt, mod := newRuntimeModule(t, "m")
	defer rt.Close(ctx)

	writeMemory(t, mod, []byte{1, 2, 3, 4, 5})

	c := snapshot.NewCoordinator()
	snap, err := c.CaptureSnapshot(mod)
	if err != nil {
		t.Fatal(err)
	}

	cd := snap.CompressedData()
	if len(cd) == 0 {
		t.Fatal("compressed data is empty")
	}

	// Decompress and verify it matches Data().
	decompressed := decompressGzip(t, cd)
	data := snap.Data()
	var expected []byte
	for _, d := range data {
		expected = append(expected, d...)
	}
	if !bytes.Equal(decompressed, expected) {
		t.Fatal("compressed data does not match data")
	}
}

func TestCompressedData_IncrementalStrictSmaller(t *testing.T) {
	ctx, rt, mod := newRuntimeModule(t, "m")
	defer rt.Close(ctx)

	writeMemory(t, mod, make([]byte, 100))

	c := snapshot.NewCoordinator()
	base, err := c.CaptureSnapshot(mod)
	if err != nil {
		t.Fatal(err)
	}

	baseCompressedLen := len(base.CompressedData())

	// Change just one byte.
	mod.Memory().WriteByte(50, 42) //nolint:errcheck

	inc, err := c.CaptureIncremental(base, mod)
	if err != nil {
		t.Fatal(err)
	}

	incCompressedLen := len(inc.CompressedData())
	if incCompressedLen >= baseCompressedLen {
		// The diff representation should normally be smaller for a 1-byte
		// change out of 100 bytes. If not, the implementation must have
		// fallen back to a full snapshot (which is not incremental).
		// Just verify the data is correct.
		data := inc.Data()
		if data[0][50] != 42 {
			t.Fatal("incremental data incorrect")
		}
	}
}

