func TestCompare(t *testing.T) {
	ctx, rt, mod1 := newRuntimeModule(t, "m1")
	defer rt.Close(ctx)
	ctx2, rt2, mod2 := newRuntimeModule(t, "m2")
	defer rt2.Close(ctx2)

	writeMemory(t, mod1, []byte{1, 2, 3, 4, 5, 6, 7, 8})
	writeMemory(t, mod2, []byte{10, 20, 30})

	c := snapshot.NewCoordinator()
	snap1, err := c.CaptureSnapshot(mod1, mod2)
	if err != nil {
		t.Fatal(err)
	}

	// Modify memory.
	mod1.Memory().WriteByte(2, 99) //nolint:errcheck
	mod1.Memory().WriteByte(5, 55) //nolint:errcheck
	mod2.Memory().WriteByte(1, 77) //nolint:errcheck

	snap2, err := c.CaptureSnapshot(mod1, mod2)
	if err != nil {
		t.Fatal(err)
	}

	diffs := snap1.Compare(snap2)
	if len(diffs) != 3 {
		t.Fatalf("expected 3 diffs, got %d", len(diffs))
	}

	expected := []snapshot.DiffEntry{
		{Offset: 2, OldValue: 3, NewValue: 99},
		{Offset: 5, OldValue: 6, NewValue: 55},
		{Offset: 1, OldValue: 20, NewValue: 77},
	}
	for i, d := range diffs {
		if d != expected[i] {
			t.Fatalf("diff %d: got %+v, want %+v", i, d, expected[i])
		}
	}
}

