// RestoreSnapshot
// ---------------------------------------------------------------------------

func TestRestoreSnapshot_IdentityMatch(t *testing.T) {
	ctx, rt, m1 := newRuntimeModule(t, "m1")
	defer rt.Close(ctx)
	ctx2, rt2, m2 := newRuntimeModule(t, "m2")
	defer rt2.Close(ctx2)

	writeMemory(t, m1, []byte{1, 2, 3, 4, 5})
	writeMemory(t, m2, []byte{10, 20, 30, 40})

	c := snapshot.NewCoordinator()
	snap, err := c.CaptureSnapshot(m1, m2)
	if err != nil {
		t.Fatal(err)
	}

	// Modify memory before restore.
	m1.Memory().WriteByte(0, 99) //nolint:errcheck
	m2.Memory().WriteByte(0, 88) //nolint:errcheck

	// Restore with identity match (order doesn't matter).
	err = c.RestoreSnapshot(snap, m2, m1)
	if err != nil {
		t.Fatal(err)
	}

	if b, _ := m1.Memory().ReadByte(0); b != 1 {
		t.Fatalf("m1[0] = %d, want 1", b)
	}
	if b, _ := m2.Memory().ReadByte(0); b != 10 {
		t.Fatalf("m2[0] = %d, want 10", b)
	}
}

func TestRestoreSnapshot_PositionalFallback(t *testing.T) {
	ctx, rt, m1 := newRuntimeModule(t, "m1")
	defer rt.Close(ctx)
	ctx2, rt2, m2 := newRuntimeModule(t, "m2")
	defer rt2.Close(ctx2)

	writeMemory(t, m1, []byte{1, 2, 3})
	writeMemory(t, m2, []byte{4, 5, 6})

	c := snapshot.NewCoordinator()
	snap, err := c.CaptureSnapshot(m1, m2)
	if err != nil {
		t.Fatal(err)
	}

	// Different instances (different pointers) — should fall back to positional.
	m1copy := newRawModule(t, "m1copy")
	m2copy := newRawModule(t, "m2copy")
	defer m1copy.rt.Close(m1copy.ctx)
	defer m2copy.rt.Close(m2copy.ctx)

	writeMemory(t, m1copy.mod, []byte{0xFF, 0xFF, 0xFF})
	writeMemory(t, m2copy.mod, []byte{0xEE, 0xEE, 0xEE})

	err = c.RestoreSnapshot(snap, m1copy.mod, m2copy.mod)
	if err != nil {
		t.Fatal(err)
	}

	if b, _ := m1copy.mod.Memory().ReadByte(0); b != 1 {
		t.Fatalf("m1copy[0] = %d, want 1", b)
	}
	if b, _ := m2copy.mod.Memory().ReadByte(0); b != 4 {
		t.Fatalf("m2copy[0] = %d, want 4", b)
	}
}

func TestRestoreSnapshot_FewerModules(t *testing.T) {
	ctx, rt, m1 := newRuntimeModule(t, "m1")
	defer rt.Close(ctx)
	ctx2, rt2, m2 := newRuntimeModule(t, "m2")
	defer rt2.Close(ctx2)

	writeMemory(t, m1, []byte{1, 2, 3})
	writeMemory(t, m2, []byte{4, 5, 6})

	c := snapshot.NewCoordinator()
	snap, err := c.CaptureSnapshot(m1, m2)
	if err != nil {
		t.Fatal(err)
	}

	// Only provide m1 (matches by identity). m2 should be silently skipped.
	m1.Memory().WriteByte(0, 99) //nolint:errcheck
	m2.Memory().WriteByte(0, 88) //nolint:errcheck

	err = c.RestoreSnapshot(snap, m1)
	if err != nil {
		t.Fatal(err)
	}

	if b, _ := m1.Memory().ReadByte(0); b != 1 {
		t.Fatalf("m1[0] = %d, want 1", b)
	}
	// m2 should be unchanged.
	if b, _ := m2.Memory().ReadByte(0); b != 88 {
		t.Fatalf("m2[0] = %d, want 88 (unchanged)", b)
	}
}

func TestRestoreSnapshot_NoModulesMatched(t *testing.T) {
	ctx, rt, m1 := newRuntimeModule(t, "m1")
	defer rt.Close(ctx)

	writeMemory(t, m1, []byte{1, 2, 3})

	c := snapshot.NewCoordinator()
	snap, err := c.CaptureSnapshot(m1)
	if err != nil {
		t.Fatal(err)
	}

	// Different module instance, count matches so positional applies.
	other := newRawModule(t, "other")
	defer other.rt.Close(other.ctx)

	writeMemory(t, other.mod, []byte{9, 9, 9})

	err = c.RestoreSnapshot(snap, other.mod)
	if err != nil {
		t.Fatal(err)
	}
	if b, _ := other.mod.Memory().ReadByte(0); b != 1 {
		t.Fatalf("other[0] = %d, want 1 (positional restore)", b)
	}
}

func TestRestoreSnapshot_IncompatibleModule(t *testing.T) {
	ctx, rt, m1 := newRuntimeModule(t, "m1")
	defer rt.Close(ctx)
	m1copy := newRawModule(t, "m1copy")
	defer m1copy.rt.Close(m1copy.ctx)

	writeMemory(t, m1, []byte{1, 2, 3})

	c := snapshot.NewCoordinator()
	snap, err := c.CaptureSnapshot(m1)
	if err != nil {
		t.Fatal(err)
	}

	err = c.RestoreSnapshot(snap, m1, m1copy.mod)
	if err == nil || !strings.Contains(err.Error(), "incompatible module") {
		t.Fatalf("expected 'incompatible module', got: %v", err)
	}
}

func TestRestoreSnapshot_NilSnapshot(t *testing.T) {
	c := snapshot.NewCoordinator()
	err := c.RestoreSnapshot(nil)
	if err == nil || err.Error() != "snapshot is nil" {
		t.Fatalf("expected 'snapshot is nil', got: %v", err)
	}
}

// ---------------------------------------------------------------------------
// Registry
// ---------------------------------------------------------------------------

func TestRegistry(t *testing.T) {
	c1 := snapshot.NewCoordinator()
	c2 := snapshot.NewCoordinator()

	snapshot.Register("alpha", c1)
	snapshot.Register("beta", c2)

	got, ok := snapshot.Get("alpha")
	if !ok || got != c1 {
		t.Fatal("failed to get 'alpha'")
	}
	got, ok = snapshot.Get("beta")
	if !ok || got != c2 {
		t.Fatal("failed to get 'beta'")
	}

	// Unknown name.
	_, ok = snapshot.Get("nonexistent")
	if ok {
		t.Fatal("expected false for nonexistent")
	}

	// Replace existing.
	c1new := snapshot.NewCoordinator()
	snapshot.Register("alpha", c1new)
	got, ok = snapshot.Get("alpha")
	if !ok || got != c1new {
		t.Fatal("failed to replace")
	}

	// Unregister.
	snapshot.Unregister("alpha")
	_, ok = snapshot.Get("alpha")
	if ok {
		t.Fatal("expected false after unregister")
	}
}

func TestRegistry_ConcurrentSafe(t *testing.T) {
	var wg sync.WaitGroup
	for i := 0; i < 20; i++ {
		wg.Add(1)
		go func(i int) {
			defer wg.Done()
			name := fmt.Sprintf("c%d", i)
			snapshot.Register(name, snapshot.NewCoordinator())
			snapshot.Get(name)
			snapshot.Unregister(name)
		}(i)
	}
	wg.Wait()
}

// ---------------------------------------------------------------------------
// Context helpers
// ---------------------------------------------------------------------------

func TestContextHelpers(t *testing.T) {
	ctx := context.Background()

	if c := snapshot.GetCoordinator(ctx); c != nil {
		t.Fatal("expected nil from empty context")
	}

	c := snapshot.NewCoordinator()
	ctx2 := snapshot.WithCoordinator(ctx, c)
	if got := snapshot.GetCoordinator(ctx2); got != c {
		t.Fatal("expected to retrieve coordinator")
	}

	// Original context unchanged.
	if c := snapshot.GetCoordinator(ctx); c != nil {
		t.Fatal("original context should remain nil")
	}
}

// ---------------------------------------------------------------------------
// Chain
// ---------------------------------------------------------------------------

func TestChain(t *testing.T) {
	ctx, rt, mod := newRuntimeModule(t, "m")
	defer rt.Close(ctx)

	c := snapshot.NewCoordinator()
	s1, _ := c.CaptureSnapshot(mod)
	s2, _ := c.CaptureSnapshot(mod)

	ch := snapshot.NewChain()
	if ch.Len() != 0 {
		t.Fatalf("expected len 0, got %d", ch.Len())
	}
	if h := ch.Head(); h != nil {
		t.Fatal("expected nil head")
	}

	ch.Push(s1)
	ch.Push(s2)

	if ch.Len() != 2 {
		t.Fatalf("expected len 2, got %d", ch.Len())
	}
	if h := ch.Head(); h != s2 {
		t.Fatal("head should be s2")
	}

	snaps := ch.Snapshots()
	if len(snaps) != 2 || snaps[0] != s1 || snaps[1] != s2 {
		t.Fatal("snapshots not oldest-first")
	}

	// Mutating returned copy shouldn't affect chain.
	snaps[0] = nil
	if ch.Len() != 2 {
		t.Fatal("chain mutated through returned copy")
	}
}

