// Marshal / Unmarshal
// ---------------------------------------------------------------------------

func TestMarshalUnmarshal(t *testing.T) {
	ctx, rt, mod := newRuntimeModule(t, "m")
	defer rt.Close(ctx)

	writeMemory(t, mod, []byte{1, 2, 3, 4, 5})

	c := snapshot.NewCoordinator()
	snap, err := c.CaptureSnapshot(mod)
	if err != nil {
		t.Fatal(err)
	}
	snap.SetTag("env", "test")
	snap.SetTag("arch", "wasm")

	data, err := snapshot.MarshalSnapshot(snap)
	if err != nil {
		t.Fatal(err)
	}

	restored, err := snapshot.UnmarshalSnapshot(data)
	if err != nil {
		t.Fatal(err)
	}

	// Data should match.
	origData := snap.Data()
	restData := restored.Data()
	if len(origData) != len(restData) {
		t.Fatalf("module count: %d vs %d", len(origData), len(restData))
	}
	for i := range origData {
		if !bytes.Equal(origData[i], restData[i]) {
			t.Fatalf("module %d data mismatch", i)
		}
	}

	// Version.
	if restored.Version() != snap.Version() {
		t.Fatalf("version: %d vs %d", restored.Version(), snap.Version())
	}

	// Tags.
	origTags := snap.Tags()
	restTags := restored.Tags()
	if len(origTags) != len(restTags) {
		t.Fatalf("tag count: %d vs %d", len(origTags), len(restTags))
	}
	for k, v := range origTags {
		if restTags[k] != v {
			t.Fatalf("tag %q: %q vs %q", k, v, restTags[k])
		}
	}
}

func TestMarshalUnmarshal_RoundTrip(t *testing.T) {
	ctx, rt, mod := newRuntimeModule(t, "m")
	defer rt.Close(ctx)

	c := snapshot.NewCoordinator()
	snap, err := c.CaptureSnapshot(mod)
	if err != nil {
		t.Fatal(err)
	}

	data, err := snapshot.MarshalSnapshot(snap)
	if err != nil {
		t.Fatal(err)
	}

