	if err != nil {
		t.Fatal(err)
	}

	if restored.Version() != snap.Version() {
		t.Fatal("version mismatch")
	}
}

func TestUnmarshalSnapshot_Error(t *testing.T) {
	_, err := snapshot.UnmarshalSnapshot([]byte("garbage"))
	if err == nil {
		t.Fatal("expected unmarshal error")
	}
}

func TestMarshalNilSnapshot(t *testing.T) {
	_, err := snapshot.MarshalSnapshot(nil)
