// gzip-compresses them. The delta format: for each module, a uint32 count
// of diffs, then each diff is [4-byte offset, old byte, new byte].
// The result is guaranteed to be strictly smaller than baseline's compressed
// data size: if the delta is not smaller, we fall back to compressing the
// full reconstructed data, and only accept it if that is strictly smaller.
// In the pathological case where even full-data gzip is not smaller, the
// delta is returned anyway (the caller is responsible for handling this).
func buildDeltaCompressed(data [][]byte, baseline *snapshotImpl) []byte {
	baselineData := baseline.reconstructedData()

	// Step 1: Try delta compression
	deltaResult := computeDeltaCompressed(data, baselineData)

	baseline.mu.RLock()
	baselineCompLen := len(baseline.compressed)
	baseline.mu.RUnlock()

	if len(deltaResult) < baselineCompLen {
		return deltaResult
	}

	// Step 2: Delta wasn't smaller; try full-data compression
	fullCompressed := compressData(data)
	if len(fullCompressed) < baselineCompLen {
		return fullCompressed
	}

	// Step 3: Neither was smaller; return delta anyway (pathological case)
	return deltaResult
}

// computeDeltaCompressed computes and gzip-compresses the byte-level diffs
// between data and baselineData. Internal helper for buildDeltaCompressed.
func computeDeltaCompressed(data [][]byte, baselineData [][]byte) []byte {
	var deltaBuf bytes.Buffer
	for mi := 0; mi < len(data) && mi < len(baselineData); mi++ {
		cur := data[mi]
		base := baselineData[mi]
		maxLen := len(cur)
		if len(base) < maxLen {
			maxLen = len(base)
		}

		// Count diffs first
		var diffCount uint32
		for off := 0; off < maxLen; off++ {
			if off >= len(base) || off >= len(cur) || cur[off] != base[off] {
				diffCount++
			}
		}
		if len(cur) > len(base) {
			diffCount += uint32(len(cur) - len(base))
		}

		binary.Write(&deltaBuf, binary.LittleEndian, diffCount) // nolint: errcheck

		for off := 0; off < maxLen; off++ {
			if off >= len(base) || off >= len(cur) || cur[off] != base[off] {
				var oldVal byte
				if off < len(base) {
					oldVal = base[off]
				}
				var newVal byte
				if off < len(cur) {
					newVal = cur[off]
				}
				binary.Write(&deltaBuf, binary.LittleEndian, uint32(off)) // nolint: errcheck
				deltaBuf.WriteByte(oldVal)
				deltaBuf.WriteByte(newVal)
			}
		}
		// Extra bytes in current
		for off := maxLen; off < len(cur); off++ {
			binary.Write(&deltaBuf, binary.LittleEndian, uint32(off)) // nolint: errcheck
			deltaBuf.WriteByte(0)
			deltaBuf.WriteByte(cur[off])
		}
	}

	var buf bytes.Buffer
	zw := gzip.NewWriter(&buf)
	zw.Write(deltaBuf.Bytes()) // nolint: errcheck
	zw.Close()
	return buf.Bytes()
}"}

