 */
export const typeMapSet = (transaction, parent, key, value) => {
  const left = parent._map.get(key) || null
  const doc = transaction.doc
  const ownClientId = doc.clientID
  let content
  if (value == null) {
    content = new ContentAny([value])
  } else {
    switch (value.constructor) {
      case Number:
      case Object:
      case Boolean:
      case Array:
      case String:
      case Date:
      case BigInt:
        content = new ContentAny([value])
        break
      case Uint8Array:
        content = new ContentBinary(/** @type {Uint8Array} */ (value))
        break
      case Doc:
        content = new ContentDoc(/** @type {Doc} */ (value))
        break
      default:
        if (value instanceof YType) {
          content = new ContentType(/** @type {any} */ (value))
        } else {
          throw new Error('Unexpected content type')
        }
    }
  }

  // Conflict detection: check if this key already has a pending write in this transaction
  const parentKey = (parent._item ? parent._item.id.client + '_' + parent._item.id.clock : 'root') + ':' + key
  const pendingWrites = transaction._pendingMapWrites
  const existingPending = pendingWrites.get(parentKey)

  if (existingPending && existingPending.length > 0) {
    const policy = /** @type {'allow'|'collect'|'error'} */ (doc._mapConflictPolicy || 'allow')
    if (policy !== 'allow') {
      const source = transaction.local ? 'local' : 'remote'

      // Determine if incoming value or any existing write is ambiguous (ContentType/ContentDoc)
      const incomingAmbiguous = content && (content.constructor.name === 'ContentType' || content.constructor.name === 'ContentDoc')
      const existingAmbiguous = existingPending.some(w => {
        if (w.item && w.item.content) {
          const name = w.item.content.constructor.name
          return name === 'ContentType' || name === 'ContentDoc'
        }
        return false
      })
      const isAmbiguous = incomingAmbiguous || existingAmbiguous

      const parentId = (parent._item ? parent._item.id.client + '_' + parent._item.id.clock : 'root')
      const writeDescs = existingPending.map(w => ({ type: w.type, value: w.value }))
      writeDescs.push({ type: 'set', value })

      const writes = writeDescs.map(w => ({
        snapshot: {
          summary: w.type === 'delete'
            ? 'delete key "' + key + '"'
            : 'set key "' + key + '" to (' + (w.value != null ? (w.value.constructor ? w.value.constructor.name : typeof w.value) : 'null') + ')'
        }
      }))

      const conflictType = existingPending.some(w => w.type === 'delete') ? 'delete-set' : 'set-set'
      const conflict = {
        key,
        parentId,
        type: conflictType,
        source,
        message: 'Conflicting map writes for key "' + key + '" on parent ' + parentId + ': ' + writeDescs.map(w => w.type).join(' vs '),
        writes,
        resolution: {
          winner: policy === 'error' ? 'rejected' : 'last-write-wins (LWW)',
          strategy: policy,
          deterministic: true
        },
        ...(isAmbiguous ? { ambiguous: true } : {})
      }

      if (policy === 'error') {
        throw new MapConflictError('Conflicting map writes for key "' + key + '"', [conflict])
      } else if (policy === 'collect') {
        doc._mapConflicts.push(conflict)
      }
    }
  }

  // Register this set as a pending write
  const newItem = new Item(createID(ownClientId, getState(doc.store, ownClientId)), left, left && left.lastId, null, null, parent, key, content)
  if (!pendingWrites.has(parentKey)) {
    pendingWrites.set(parentKey, [])
  }
  pendingWrites.get(parentKey).push({ type: 'set', value, item: newItem })

  newItem.integrate(transaction, 0)
}"}

