import * as Y from '../src/index.js'
import * as t from 'lib0/testing'

/**
 * Helper: encode state as update (V1) and apply it to simulate a remote update.
 */
const simulateRemoteUpdate = (sourceDoc, targetDoc) => {
  const update = Y.encodeStateAsUpdate(sourceDoc)
  Y.applyUpdate(targetDoc, update)
}

/**
 * @param {t.TestCase} _tc
 */
export const testMapConflictPolicyAllow = _tc => {
  const doc = new Y.Doc({ mapConflictPolicy: 'allow' })
  const ymap = doc.get()
  ymap.setAttr('key1', 'value1')
  ymap.setAttr('key1', 'value2')
  t.assert(ymap.getAttr('key1') === 'value2', 'allow mode: last write wins')
  t.assert(doc.getMapConflicts().length === 0, 'allow mode: no conflicts collected')
}

/**
 * @param {t.TestCase} _tc
 */
export const testMapConflictPolicyCollect = _tc => {
  const doc = new Y.Doc({ mapConflictPolicy: 'collect' })
  const ymap = doc.get()
  ymap.setAttr('key1', 'value1')
  ymap.setAttr('key1', 'value2')
  t.assert(ymap.getAttr('key2') === undefined, 'collect mode: conflict on key1, key2 not set')
  const conflicts = doc.getMapConflicts()
  t.assert(conflicts.length > 0, 'collect mode: conflicts were recorded')
  t.assert(conflicts[0].type === 'set-set', 'collect mode: conflict type is set-set')
  t.assert(conflicts[0].key === 'key1', 'collect mode: conflict key is key1')
}

/**
 * @param {t.TestCase} _tc
 */
export const testMapConflictCollectDeleteSet = _tc => {
  const doc = new Y.Doc({ mapConflictPolicy: 'collect' })
  const ymap = doc.get()
  ymap.setAttr('key1', 'value1')
  ymap.deleteAttr('key1')
  ymap.setAttr('key1', 'value2')
  const conflicts = doc.getMapConflicts()
  // Should have collected at least one delete-set conflict
  const hasDeleteSet = conflicts.some(c => c.type === 'delete-set')
  t.assert(hasDeleteSet, 'collect mode: delete-set conflict detected')
}

/**
 * @param {t.TestCase} _tc
 */
export const testMapConflictErrorThrows = _tc => {
  const doc = new Y.Doc({ mapConflictPolicy: 'error' })
  const ymap = doc.get()
  let threw = false
  try {
    ymap.setAttr('key1', 'value1')
    ymap.setAttr('key1', 'value2')
  } catch (err) {
    threw = true
    t.assert(err.name === 'MapConflictError', 'error mode: error is MapConflictError')
    t.assert(Array.isArray(err.conflicts), 'error mode: err.conflicts is an array')
    t.assert(err.conflicts.length > 0, 'error mode: err.conflicts has at least one conflict')
    const conflict = err.conflicts[0]
    t.assert(conflict.key === 'key1', 'error mode: conflict.key is key1')
    t.assert(conflict.type === 'set-set', 'error mode: conflict.type is set-set')
    t.assert(typeof conflict.parentId === 'string', 'error mode: conflict.parentId is a string')
    t.assert(conflict.source === 'local', 'error mode: conflict.source is local')
    t.assert(typeof conflict.message === 'string', 'error mode: conflict.message is a string')
    t.assert(conflict.message.length > 0, 'error mode: conflict.message is non-empty')
    t.assert(Array.isArray(conflict.writes), 'error mode: conflict.writes is an array')
    t.assert(conflict.writes.length >= 2, 'error mode: conflict.writes has at least 2 entries')
    for (const write of conflict.writes) {
      t.assert(typeof write.snapshot.summary === 'string', 'error mode: write.snapshot.summary is a string')
      t.assert(write.snapshot.summary.length > 0, 'error mode: write.snapshot.summary is non-empty')
    }
    t.assert(conflict.resolution.winner === 'rejected', 'error mode: resolution.winner is rejected')
    t.assert(conflict.resolution.strategy === 'error', 'error mode: resolution.strategy is error')
    t.assert(conflict.resolution.deterministic === true, 'error mode: resolution.deterministic is true')
  }
  t.assert(threw, 'error mode: MapConflictError was thrown')
}

/**
 * @param {t.TestCase} _tc
 */
export const testMapConflictErrorAtomicNoPartial = _tc => {
  const doc = new Y.Doc({ mapConflictPolicy: 'error' })
  const ymap = doc.get()
  ymap.setAttr('key1', 'initial')
  try {
    ymap.setAttr('key1', 'overwrite')
    t.fail('error mode: should have thrown')
  } catch (err) {
    t.assert(err.name === 'MapConflictError')
  }
  // The initial value should still be there (no partial application of conflicting write)
  t.assert(ymap.getAttr('key1') === 'initial', 'error mode: no partial application - initial value preserved')
}

/**
 * @param {t.TestCase} _tc
 */
export const testMapConflictErrorDeleteSetAtomic = _tc => {
  const doc = new Y.Doc({ mapConflictPolicy: 'error' })
  const ymap = doc.get()
  ymap.setAttr('key1', 'value1')
  ymap.setAttr('key2', 'safe')
  let threw = false
  try {
    ymap.deleteAttr('key1')
    ymap.setAttr('key1', 'value2')
  } catch (err) {
    threw = true
    t.assert(err.name === 'MapConflictError')
    // The delete should NOT have been applied
    t.assert(ymap.getAttr('key1') === 'value1', 'error mode: delete-set atomic - initial value preserved')
    t.assert(ymap.getAttr('key2') === 'safe', 'error mode: unrelated key2 unchanged')
  }
  t.assert(threw, 'error mode: delete-set should throw')
}

/**
 * @param {t.TestCase} _tc
 */
export const testMapConflictSummaryByType = _tc => {
  const doc = new Y.Doc({ mapConflictPolicy: 'collect' })
  const ymap = doc.get()
  ymap.setAttr('a', 1)
  ymap.setAttr('a', 2)
  ymap.setAttr('b', 3)
  ymap.setAttr('b', 4)
  const summary = doc.getMapConflictSummary()
  t.assert(summary.count >= 2, 'summary.count >= 2')
  t.assert(summary.total >= 2, 'summary.total >= 2')
  t.assert(typeof summary.byType === 'object', 'summary.byType is an object')
  t.assert(summary.byType['set-set'] >= 2, 'summary.byType["set-set"] >= 2')
  t.assert(typeof summary.byKey === 'object', 'summary.byKey is an object')
  t.assert(summary.byKey['a'] >= 1, 'summary.byKey["a"] >= 1')
  t.assert(summary.byKey['b'] >= 1, 'summary.byKey["b"] >= 1')
  t.assert(typeof summary.byParent === 'object', 'summary.byParent is an object')
  t.assert(typeof summary.bySource === 'object', 'summary.bySource is an object')
  t.assert(summary.bySource['local'] >= 2, 'summary.bySource["local"] >= 2')
  // Test index access
  t.assert(summary.byType['set-set'] === summary.byType['set-set'], 'index access works')
}

/**
 * @param {t.TestCase} _tc
 */
export const testMapConflictSummaryWithDelete = _tc => {
  const doc = new Y.Doc({ mapConflictPolicy: 'collect' })
  const ymap = doc.get()
  ymap.setAttr('k', 1)
  ymap.deleteAttr('k')
  ymap.setAttr('k', 2)
  const summary = doc.getMapConflictSummary()
  t.assert(summary.count >= 1, 'delete-set summary has count')
  t.assert(summary.total >= 1, 'delete-set summary has total')
}

/**
 * @param {t.TestCase} _tc
 */
export const testMapConflictAmbiguousContentType = _tc => {
  const doc = new Y.Doc({ mapConflictPolicy: 'collect' })
  const ymap = doc.get()
  const nested = new Y.Type()
  ymap.setAttr('key1', nested)
  ymap.setAttr('key1', 'plain')
  const conflicts = doc.getMapConflicts()
  const ambigConflict = conflicts.find(c => c.key === 'key1')
  t.assert(ambigConflict !== undefined, 'ambig conflict found for key1')
  t.assert(ambigConflict.ambiguous === true, 'ambig conflict set for ContentType value')
}

/**
 * @param {t.TestCase} _tc
 */
export const testMapConflictDefaultPolicy = _tc => {
  const doc = new Y.Doc()
  const ymap = doc.get()
  ymap.setAttr('k', 1)
  ymap.setAttr('k', 2)
  t.assert(ymap.getAttr('k') === 2, 'default policy is allow')
  t.assert(doc.getMapConflicts().length === 0, 'default policy no conflicts')
}

/**
 * @param {t.TestCase} _tc
 */
export const testMapConflictRemoteUpdateCollect = _tc => {
  const doc1 = new Y.Doc({ mapConflictPolicy: 'collect' })
  const doc2 = new Y.Doc({ mapConflictPolicy: 'collect' })
  const map1 = doc1.get()
  const map2 = doc2.get()
  map1.setAttr('key', 'from1')
  map2.setAttr('key', 'from2')
  // Apply doc1's update to doc2 (simulating a remote merge)
  const update1 = Y.encodeStateAsUpdate(doc1)
  try {
    Y.applyUpdate(doc2, update1)
  } catch (e) {
    // Ignore any errors
  }
  const conflicts2 = doc2.getMapConflicts()
  // There should be at least a conflict from the remote merge
  t.assert(conflicts2.length > 0, 'remote update: conflicts recorded')
  // The last write should have won (CRDT behavior)
  t.assert(map2.getAttr('key') !== undefined, 'remote update: key still accessible')
}

/**
 * @param {t.TestCase} _tc
 */
export const testMapConflictObjectStructure = _tc => {
  const doc = new Y.Doc({ mapConflictPolicy: 'collect' })
  const ymap = doc.get()
  ymap.setAttr('objKey', { a: 1 })
  ymap.setAttr('objKey', { b: 2 })
  const conflicts = doc.getMapConflicts()
  t.assert(conflicts.length > 0, 'conflict recorded for objKey')
  const c = conflicts[0]
  // Check every required field
  t.assert(typeof c.key === 'string', 'conflict has key string')
  t.assert(typeof c.parentId === 'string', 'conflict has parentId string')
  t.assert(['set-set', 'delete-set'].includes(c.type), 'conflict type is valid')
  t.assert(['local', 'remote', 'mixed'].includes(c.source), 'conflict source is valid')
  t.assert(typeof c.message === 'string' && c.message.length > 0, 'conflict has non-empty message')
  t.assert(Array.isArray(c.writes), 'conflict has writes array')
