func TestJSONPathQuery_Dict(t *testing.T) {
	// Build a starlark.Dict document
	doc := starlark.NewDict(4)
	doc.SetKey(starlark.String("name"), starlark.String("test"))
	doc.SetKey(starlark.String("count"), starlark.MakeInt(42))

