	doc.SetKey(starlark.String("nested"), inner)

	// Test query
	mod := JSONPathAPI["jsonpath"].(*starlarkstruct.Module)
	queryFn := mod.Members["query"].(*starlark.Builtin)

	// Query root
	thread := &starlark.Thread{Name: "test"}
	val, err := starlark.Call(thread, queryFn, starlark.Tuple{doc, starlark.String("$")}, nil)
	if err != nil {
		t.Fatal(err)
